update public.article_cache set translation = '{"sentences": [{"text": "최근 인터넷에서 흥미로운 실험이 화제가 되었어요.", "idx": 0, "translation": "Recently, an interesting experiment became a topic of discussion on the internet.", "vocab": [{"ko": "최근", "en": "recently", "note": "adverb of time"}, {"ko": "흥미롭다", "en": "to be interesting", "note": "~ㄴ/은 adjective form"}, {"ko": "화제가 되다", "en": "become a topic", "note": "fixed expression"}], "analysis": [{"type": "expression", "label": "화제가 되다", "exp": "to become a topic of discussion", "example_in_sentence": "화제가 되었어요"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Lets an adjective describe a noun. 흥미롭다 is ㅂ-irregular (ㅂ becomes 우): 흥미롭다 → 흥미로운 실험 = an interesting experiment.", "example_in_sentence": "흥미로운 실험"}]}, {"text": "한 사람이 큐알코드(QR Code)를 손으로 직접 그려서 만들었는데, 놀랍게도 스마트폰으로 읽을 수 있었다고 해요.", "idx": 1, "translation": "Someone reportedly drew a QR code by hand, and surprisingly, a smartphone could read it.", "vocab": [{"ko": "큐알코드", "en": "QR Code", "note": "foreign loanword"}, {"ko": "놀랍게도", "en": "surprisingly", "note": "adverbial form of 놀랍다"}, {"ko": "읽다", "en": "read", "note": "verb"}], "analysis": [{"type": "grammar", "label": "~아/어서 (sequence/means)", "exp": "Links an action to the next one done by means of it. 그리다 → 그려서 만들다 = to make by drawing.", "example_in_sentence": "그려서 만들었는데"}, {"type": "grammar", "label": "~았/었는데", "exp": "Sets up background for what comes next: ''did ~, and ...''. 만들다 → 만들었는데 = (he) made it, and ...", "example_in_sentence": "만들었는데"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can / be able to''. 읽다 → 읽을 수 있었다 = could be read.", "example_in_sentence": "읽을 수 있었다"}, {"type": "grammar", "label": "~다고 해요", "exp": "Reports something heard: ''they say ~''. 있었다 → 있었다고 해요 = it is said (it) could.", "example_in_sentence": "읽을 수 있었다고 해요"}]}, {"text": "큐알코드는 보통 컴퓨터로 정확하게 만들어져요.", "idx": 2, "translation": "QR Codes are normally created accurately by computer.", "vocab": [{"ko": "보통", "en": "normally, usually", "note": "adverb"}, {"ko": "정확하다", "en": "to be accurate (정확하게 = accurately)", "note": "adverbial form"}], "analysis": [{"type": "grammar", "label": "~아/어지다 (passive)", "exp": "Makes a verb passive. 만들다 → 만들어지다 → 만들어져요 = are made.", "example_in_sentence": "만들어져요"}, {"type": "grammar", "label": "~(으)로 (means)", "exp": "Particle marking the tool or means: ''by / with''. 컴퓨터 → 컴퓨터로 = by computer.", "example_in_sentence": "컴퓨터로"}]}, {"text": "하지만 이번 실험에서는 종이에 펜으로 직접 그린 코드도 작동한다는 것을 보여줬어요.", "idx": 3, "translation": "However, in this experiment, it was shown that code drawn directly with a pen on paper also works.", "vocab": [{"ko": "종이", "en": "paper", "note": "noun"}, {"ko": "펜", "en": "pen", "note": "noun"}, {"ko": "작동하다", "en": "to work, function", "note": "verb"}], "analysis": [{"type": "grammar", "label": "~ㄴ/는다는 것을 보여주다", "exp": "Means ''to show that ~''. 작동하다 → 작동한다는 것을 보여줬어요 = showed that it works.", "example_in_sentence": "작동한다는 것을 보여줬어요"}, {"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier for verbs. 그리다 → 그린 코드 = code that was drawn.", "example_in_sentence": "그린 코드"}]}, {"text": "물론 완벽하게 그리기는 매우 어렵다고 해요.", "idx": 4, "translation": "Of course, they say drawing it perfectly is very hard.", "vocab": [{"ko": "물론", "en": "of course", "note": "adverb"}, {"ko": "완벽하다", "en": "to be perfect (완벽하게 = perfectly)", "note": "adverbial form"}, {"ko": "어렵다", "en": "to be difficult", "note": "adjective"}], "analysis": [{"type": "grammar", "label": "~기는", "exp": "~기 turns a verb into a noun (''doing ~'') and 는 makes it the topic. 그리다 → 그리기는 어렵다 = drawing (it) is difficult.", "example_in_sentence": "그리기는 매우 어렵다"}, {"type": "grammar", "label": "~다고 해요", "exp": "reported speech: it is said that", "example_in_sentence": "어렵다고 해요"}]}, {"text": "이 소식은 해커 뉴스(Hacker News)라는 기술 커뮤니티에서 많은 관심을 받았어요.", "idx": 5, "translation": "This news received a lot of interest from a tech community called Hacker News.", "vocab": [{"ko": "소식", "en": "news", "note": "noun"}, {"ko": "관심을 받다", "en": "receive interest/attention", "note": "fixed expression"}, {"ko": "커뮤니티", "en": "community", "note": "foreign loanword"}], "analysis": [{"type": "expression", "label": "관심을 받다", "exp": "to receive interest/attention", "example_in_sentence": "많은 관심을 받았어요"}, {"type": "grammar", "label": "~(이)라는", "exp": "Gives the name of the noun after it: ''called ~''. 해커 뉴스라는 커뮤니티 = a community called Hacker News.", "example_in_sentence": "뉴스(Hacker News)라는 기술 커뮤니티"}]}, {"text": "사람들은 기술이 생각보다 관대하다는 점에 놀라워했어요.", "idx": 6, "translation": "People were surprised that the technology is more forgiving than they expected.", "vocab": [{"ko": "기술", "en": "technology", "note": "noun"}, {"ko": "관대하다", "en": "to be forgiving; to be lenient", "note": "adjective"}, {"ko": "생각보다", "en": "more than expected", "note": "adverbial comparative"}], "analysis": [{"type": "grammar", "label": "~다는 점", "exp": "Means ''the fact / point that ~''. 관대하다 → 관대하다는 점에 놀라다 = to be surprised that it is forgiving.", "example_in_sentence": "관대하다는 점에"}, {"type": "expression", "label": "~아/어하다", "exp": "Turns a feeling adjective into a verb for how others feel or show it. 놀랍다 → 놀라워하다 → 놀라워했어요 = (people) were amazed.", "example_in_sentence": "놀라워했어요"}, {"type": "grammar", "label": "~보다 (than)", "exp": "Particle meaning ''than''. 생각보다 관대하다 = more forgiving than (people) thought.", "example_in_sentence": "생각보다 관대하다"}]}, {"text": "전문가들은 큐알코드에 오류 수정 기능이 있어서 조금 잘못 그려도 읽을 수 있다고 설명했어요.", "idx": 7, "translation": "Experts explained that because QR Codes have an error correction function, they can be read even if drawn slightly incorrectly.", "vocab": [{"ko": "전문가", "en": "expert", "note": "noun"}, {"ko": "오류 수정 기능", "en": "error correction function", "note": "compound noun"}, {"ko": "잘못 그리다", "en": "draw incorrectly", "note": "verb phrase"}], "analysis": [{"type": "grammar", "label": "~아/어서 (reason)", "exp": "Gives a reason: ''because / so''. 있다 → 있어서 = because (it) has.", "example_in_sentence": "기능이 있어서"}, {"type": "grammar", "label": "~아/어도", "exp": "even if/though: even if drawn wrongly", "example_in_sentence": "잘못 그려도"}, {"type": "grammar", "label": "~다고 설명하다", "exp": "explain that (reported statement)", "example_in_sentence": "읽을 수 있다고 설명했어요"}]}, {"text": "하지만 여전히 손으로 그리는 것은 매우 높은 집중력이 필요한 일이에요.", "idx": 8, "translation": "However, drawing by hand is still a task that requires very high concentration.", "vocab": [{"ko": "여전히", "en": "still, nonetheless", "note": "adverb"}, {"ko": "집중력", "en": "concentration, focus", "note": "noun"}, {"ko": "필요하다", "en": "to be necessary; to need", "note": "adjective"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Lets an adjective describe a noun. 필요하다 → 필요한 일 = a task that needs (something).", "example_in_sentence": "필요한 일"}, {"type": "grammar", "label": "~이/가 필요하다", "exp": "Means ''to need ~''; the thing needed takes 이/가. 집중력이 필요한 일 = a task that needs concentration.", "example_in_sentence": "높은 집중력이 필요한"}]}], "version": "s1"}', vocab = '[{"ko": "최근", "en": "recently", "note": "adverb of time"}, {"ko": "흥미롭다", "en": "to be interesting", "note": "~ㄴ/은 adjective form"}, {"ko": "화제가 되다", "en": "become a topic", "note": "fixed expression"}, {"ko": "큐알코드", "en": "QR Code", "note": "foreign loanword"}, {"ko": "놀랍게도", "en": "surprisingly", "note": "adverbial form of 놀랍다"}, {"ko": "읽다", "en": "read", "note": "verb"}, {"ko": "보통", "en": "normally, usually", "note": "adverb"}, {"ko": "정확하다", "en": "to be accurate (정확하게 = accurately)", "note": "adverbial form"}, {"ko": "종이", "en": "paper", "note": "noun"}, {"ko": "펜", "en": "pen", "note": "noun"}, {"ko": "작동하다", "en": "to work, function", "note": "verb"}, {"ko": "물론", "en": "of course", "note": "adverb"}, {"ko": "완벽하다", "en": "to be perfect (완벽하게 = perfectly)", "note": "adverbial form"}, {"ko": "어렵다", "en": "to be difficult", "note": "adjective"}, {"ko": "소식", "en": "news", "note": "noun"}, {"ko": "관심을 받다", "en": "receive interest/attention", "note": "fixed expression"}, {"ko": "커뮤니티", "en": "community", "note": "foreign loanword"}, {"ko": "기술", "en": "technology", "note": "noun"}, {"ko": "관대하다", "en": "to be forgiving; to be lenient", "note": "adjective"}, {"ko": "생각보다", "en": "more than expected", "note": "adverbial comparative"}, {"ko": "전문가", "en": "expert", "note": "noun"}, {"ko": "오류 수정 기능", "en": "error correction function", "note": "compound noun"}, {"ko": "잘못 그리다", "en": "draw incorrectly", "note": "verb phrase"}, {"ko": "여전히", "en": "still, nonetheless", "note": "adverb"}, {"ko": "집중력", "en": "concentration, focus", "note": "noun"}, {"ko": "필요하다", "en": "to be necessary; to need", "note": "adjective"}, {"ko": "실험", "en": "experiment", "note": ""}, {"ko": "화제", "en": "hot topic", "note": ""}, {"ko": "직접", "en": "directly", "note": ""}, {"ko": "그리다", "en": "to draw", "note": ""}, {"ko": "만들다", "en": "to make", "note": ""}, {"ko": "놀랍다", "en": "to be surprising", "note": ""}, {"ko": "컴퓨터", "en": "computer", "note": ""}, {"ko": "보여주다", "en": "to show", "note": ""}, {"ko": "관심", "en": "interest/attention", "note": ""}, {"ko": "생각", "en": "thought", "note": ""}, {"ko": "놀라다", "en": "to be surprised", "note": ""}, {"ko": "오류", "en": "error", "note": ""}, {"ko": "기능", "en": "function", "note": ""}, {"ko": "설명하다", "en": "to explain", "note": ""}, {"ko": "높다", "en": "to be high", "note": ""}]', grammar = '{"patterns": [{"name": "~(으)ㄴ (adjective modifier)", "level": "Intermediate", "exp": "Lets an adjective describe a noun. 흥미롭다 is ㅂ-irregular (ㅂ becomes 우): 흥미롭다 → 흥미로운 실험 = an interesting experiment.", "ex_ko": "최근 인터넷에서 흥미로운 실험이 화제가 되었어요.", "ex_en": "Recently, an interesting experiment became a topic of discussion on the internet."}, {"name": "~아/어서 (sequence/means)", "level": "Intermediate", "exp": "Links an action to the next one done by means of it. 그리다 → 그려서 만들다 = to make by drawing.", "ex_ko": "한 사람이 큐알코드(QR Code)를 손으로 직접 그려서 만들었는데, 놀랍게도 스마트폰으로 읽을 수 있었다고 해요.", "ex_en": "Someone reportedly drew a QR code by hand, and surprisingly, a smartphone could read it."}, {"name": "~았/었는데", "level": "Intermediate", "exp": "Sets up background for what comes next: ''did ~, and ...''. 만들다 → 만들었는데 = (he) made it, and ...", "ex_ko": "한 사람이 큐알코드(QR Code)를 손으로 직접 그려서 만들었는데, 놀랍게도 스마트폰으로 읽을 수 있었다고 해요.", "ex_en": "Someone reportedly drew a QR code by hand, and surprisingly, a smartphone could read it."}, {"name": "~(으)ㄹ 수 있다", "level": "Intermediate", "exp": "Means ''can / be able to''. 읽다 → 읽을 수 있었다 = could be read.", "ex_ko": "한 사람이 큐알코드(QR Code)를 손으로 직접 그려서 만들었는데, 놀랍게도 스마트폰으로 읽을 수 있었다고 해요.", "ex_en": "Someone reportedly drew a QR code by hand, and surprisingly, a smartphone could read it."}, {"name": "~다고 해요", "level": "Intermediate", "exp": "Reports something heard: ''they say ~''. 있었다 → 있었다고 해요 = it is said (it) could.", "ex_ko": "한 사람이 큐알코드(QR Code)를 손으로 직접 그려서 만들었는데, 놀랍게도 스마트폰으로 읽을 수 있었다고 해요.", "ex_en": "Someone reportedly drew a QR code by hand, and surprisingly, a smartphone could read it."}, {"name": "~아/어지다 (passive)", "level": "Intermediate", "exp": "Makes a verb passive. 만들다 → 만들어지다 → 만들어져요 = are made.", "ex_ko": "큐알코드는 보통 컴퓨터로 정확하게 만들어져요.", "ex_en": "QR Codes are normally created accurately by computer."}, {"name": "~(으)로 (means)", "level": "Intermediate", "exp": "Particle marking the tool or means: ''by / with''. 컴퓨터 → 컴퓨터로 = by computer.", "ex_ko": "큐알코드는 보통 컴퓨터로 정확하게 만들어져요.", "ex_en": "QR Codes are normally created accurately by computer."}, {"name": "~ㄴ/는다는 것을 보여주다", "level": "Intermediate", "exp": "Means ''to show that ~''. 작동하다 → 작동한다는 것을 보여줬어요 = showed that it works.", "ex_ko": "하지만 이번 실험에서는 종이에 펜으로 직접 그린 코드도 작동한다는 것을 보여줬어요.", "ex_en": "However, in this experiment, it was shown that code drawn directly with a pen on paper also works."}, {"name": "~기는", "level": "Intermediate", "exp": "~기 turns a verb into a noun (''doing ~'') and 는 makes it the topic. 그리다 → 그리기는 어렵다 = drawing (it) is difficult.", "ex_ko": "물론 완벽하게 그리기는 매우 어렵다고 해요.", "ex_en": "Of course, they say drawing it perfectly is very hard."}, {"name": "~(이)라는", "level": "Intermediate", "exp": "Gives the name of the noun after it: ''called ~''. 해커 뉴스라는 커뮤니티 = a community called Hacker News.", "ex_ko": "이 소식은 해커 뉴스(Hacker News)라는 기술 커뮤니티에서 많은 관심을 받았어요.", "ex_en": "This news received a lot of interest from a tech community called Hacker News."}, {"name": "~다는 점", "level": "Intermediate", "exp": "Means ''the fact / point that ~''. 관대하다 → 관대하다는 점에 놀라다 = to be surprised that it is forgiving.", "ex_ko": "사람들은 기술이 생각보다 관대하다는 점에 놀라워했어요.", "ex_en": "People were surprised that the technology is more forgiving than they expected."}, {"name": "~보다 (than)", "level": "Intermediate", "exp": "Particle meaning ''than''. 생각보다 관대하다 = more forgiving than (people) thought.", "ex_ko": "사람들은 기술이 생각보다 관대하다는 점에 놀라워했어요.", "ex_en": "People were surprised that the technology is more forgiving than they expected."}, {"name": "~아/어도", "level": "Intermediate", "exp": "even if/though: even if drawn wrongly", "ex_ko": "전문가들은 큐알코드에 오류 수정 기능이 있어서 조금 잘못 그려도 읽을 수 있다고 설명했어요.", "ex_en": "Experts explained that because QR Codes have an error correction function, they can be read even if drawn slightly incorrectly."}, {"name": "~다고 설명하다", "level": "Intermediate", "exp": "explain that (reported statement)", "ex_ko": "전문가들은 큐알코드에 오류 수정 기능이 있어서 조금 잘못 그려도 읽을 수 있다고 설명했어요.", "ex_en": "Experts explained that because QR Codes have an error correction function, they can be read even if drawn slightly incorrectly."}, {"name": "~이/가 필요하다", "level": "Intermediate", "exp": "Means ''to need ~''; the thing needed takes 이/가. 집중력이 필요한 일 = a task that needs concentration.", "ex_ko": "하지만 여전히 손으로 그리는 것은 매우 높은 집중력이 필요한 일이에요.", "ex_en": "However, drawing by hand is still a task that requires very high concentration."}]}', updated_at = now() where article_id = 'mosfnmdkya16' and md5(translation) = '1e05cd5e78be14cf68ae847dd2cc831e';
update public.article_cache set translation = '{"texts": ["The Anna''s hummingbird is a small, beautiful bird. This bird''s most special feature is its shimmering purple feathers.", "But there is a surprising fact. This purple color is not because of pigment. It appears purple because of the very small structures inside the feathers.", "On the feathers, there are layers so small that they cannot be seen with the naked eye. These layers act like mirrors and reflect light.", "So depending on the angle from which it is viewed, the color changes. This phenomenon is one of the mysterious things that can be seen in nature. So this kind of scientific principle was hidden in the hummingbird''s beautiful color."], "sentences": [{"text": "안나 벌새(Anna''s hummingbird)는 작고 아름다운 새예요.", "translation": "The Anna''s hummingbird is a small, beautiful bird.", "vocab": [{"ko": "벌새", "en": "hummingbird", "note": ""}, {"ko": "아름답다", "en": "to be beautiful", "note": "vowel-irregular: 아름답+은 → 아름다운"}], "analysis": []}, {"text": "이 새의 가장 특별한 점은 반짝이는 보라색 깃털입니다.", "translation": "This bird''s most special feature is its shimmering purple feathers.", "vocab": [{"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "반짝이다", "en": "to sparkle, shimmer", "note": ""}, {"ko": "깃털", "en": "feather", "note": ""}], "analysis": []}, {"text": "그런데 놀라운 사실이 있어요.", "translation": "But there is a surprising fact.", "vocab": [{"ko": "놀랍다", "en": "to be surprising", "note": "ㅂ-irregular: 놀랍+은 → 놀라운"}, {"ko": "사실", "en": "fact", "note": ""}], "analysis": []}, {"text": "이 보라색은 색소 때문이 아니에요.", "translation": "This purple color is not because of pigment.", "vocab": [{"ko": "보라색", "en": "purple (color)", "note": ""}, {"ko": "색소", "en": "pigment", "note": ""}], "analysis": [{"type": "grammar", "label": "~ 때문이다 / ~ 때문에", "exp": "때문 means ''because of''. 색소 때문이 아니에요 = it is not because of pigment.", "example_in_sentence": "색소 때문이 아니에요"}]}, {"text": "깃털 안에 있는 아주 작은 구조 때문에 보라색으로 보입니다.", "translation": "It appears purple because of the very small structures inside the feathers.", "vocab": [{"ko": "구조", "en": "structure", "note": ""}, {"ko": "보이다", "en": "to be seen, to appear", "note": "passive of 보다"}], "analysis": [{"type": "grammar", "label": "~ 때문에 (because of N)", "exp": "because of (noun). 구조 → 구조 때문에 = \"because of the structure\".", "example_in_sentence": "구조 때문에"}, {"type": "grammar", "label": "~(으)로 보이다", "exp": "Means ''to look like / appear as ~''. 보라색으로 보입니다 = it looks purple.", "example_in_sentence": "보라색으로 보입니다"}]}, {"text": "깃털에는 눈에 보이지 않을 정도로 작은 층들이 있어요.", "translation": "On the feathers, there are layers so small that they cannot be seen with the naked eye.", "vocab": [{"ko": "층", "en": "layer, floor", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 정도로", "exp": "Means ''so ~ that'' / ''to the point of ~''. 보이지 않다 → 보이지 않을 정도로 작은 = so small that you can''t see them.", "example_in_sentence": "보이지 않을 정도로 작은"}, {"type": "grammar", "label": "~지 않다", "exp": "long-form negation. 보이다 → 보이지 않다 = \"to not be visible\". 보이지 않을 = \"that is not visible (modifier)\".", "example_in_sentence": "보이지 않을"}]}, {"text": "이 층들이 거울처럼 작용해서 빛을 반사합니다.", "translation": "These layers act like mirrors and reflect light.", "vocab": [{"ko": "거울", "en": "mirror", "note": ""}, {"ko": "작용하다", "en": "to act, to function", "note": ""}, {"ko": "빛", "en": "light", "note": ""}, {"ko": "반사하다", "en": "to reflect", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "reason or sequence connector. 작용하다 → 작용해서 = \"because (it) acts / and then acts\". 하다 contracts to 해서.", "example_in_sentence": "작용해서"}, {"type": "expression", "label": "~처럼", "exp": "Particle meaning ''like / as''. 거울 → 거울처럼 = like a mirror.", "example_in_sentence": "거울처럼"}]}, {"text": "그래서 보는 각도에 따라 색깔이 달라져요.", "translation": "So depending on the angle from which it is viewed, the color changes.", "vocab": [{"ko": "각도", "en": "angle", "note": ""}, {"ko": "달라지다", "en": "to change; to become different", "note": "르-irregular: 다르+아 → 달라"}, {"ko": "색깔", "en": "color", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 따라(서) (depending on / as)", "exp": "variation / dependence. 각도 → 각도에 따라 = \"depending on the angle / according to the angle\".", "example_in_sentence": "각도에 따라"}, {"type": "grammar", "label": "르 불규칙 (르 → ㄹㄹ)", "exp": "르-irregular: 다르다 → 달라(요), 모르다 → 몰라, 부르다 → 불러. Here 다르다 + 아져요 → 달라져요 = \"becomes different\".", "example_in_sentence": "달라져요"}, {"type": "expression", "label": "~아/어지다 (become)", "exp": "change-of-state suffix. 다르다 → 달라지다 = \"to become different / to change\". Marks a transition into a state.", "example_in_sentence": "달라져요"}]}, {"text": "이런 현상은 자연에서 볼 수 있는 신기한 일 중 하나입니다.", "translation": "This phenomenon is one of the amazing things you can see in nature.", "vocab": [{"ko": "현상", "en": "phenomenon", "note": ""}, {"ko": "자연", "en": "nature", "note": ""}, {"ko": "신기하다", "en": "to be amazing, mysterious", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can''. 보다 → 볼 수 있는 = that (you) can see.", "example_in_sentence": "볼 수 있는"}, {"type": "grammar", "label": "~ 중 하나", "exp": "Means ''one of ~''. 신기한 일 중 하나 = one of the amazing things.", "example_in_sentence": "신기한 일 중 하나"}]}, {"text": "벌새의 아름다운 색깔에는 이런 과학적 원리가 숨어 있었네요.", "translation": "So this kind of scientific principle was hidden in the hummingbird''s beautiful color.", "vocab": [{"ko": "과학적", "en": "scientific", "note": ""}, {"ko": "원리", "en": "principle", "note": ""}, {"ko": "숨다", "en": "to hide", "note": ""}], "analysis": [{"type": "grammar", "label": "~네요 (discovery)", "exp": "realization / mild surprise. 있다 → 있었네요 = \"oh, (it) was\". Marks discovery: \"so (it) was, huh\".", "example_in_sentence": "있었네요"}, {"type": "grammar", "label": "~아/어 있다 (resultant state)", "exp": "resulting state from a completed action. 숨다 → 숨어 있다 = \"to remain hidden\". 숨어 있었다 = \"was (kept) hidden\".", "example_in_sentence": "숨어 있었네요"}, {"type": "gra