update public.article_cache set translation = '{"texts": ["There is a very special photograph taken in 1842. It is a photograph of a cow taken in Rome, Italy.", "This photograph is said to be the oldest photograph of a living animal ever taken. It was taken more than 180 years ago from now.", "The person who took the photograph is French. His name is very long and difficult to remember.", "Taking photographs in that era was really difficult. It was not possible to take them as easily as we do now. That is why this photograph is even more precious."], "sentences": [{"text": "1842년에 찍힌 아주 특별한 사진이 있어요.", "translation": "There is a very special photograph taken in 1842.", "vocab": [{"ko": "찍히다", "en": "to be taken (passive of 찍다)", "note": "Used for photos/pictures being taken; passive voice"}, {"ko": "특별하다", "en": "to be special", "note": "Descriptive verb; 특별한 = special (modifying noun)"}], "grammar": [{"pattern": "~(으)ㄴ (past participle modifier)", "exp": "Modifies a noun with a past participle form to describe when/how the action occurred.", "example_in_sentence": "찍힌 아주 특별한 사진"}], "analysis": []}, {"text": "이탈리아 로마에서 소 한 마리를 찍은 사진이에요.", "translation": "It is a photograph of a cow taken in Rome, Italy.", "vocab": [{"ko": "소", "en": "cow", "note": "Common noun; 한 마리 = one animal (counter)"}], "grammar": [{"pattern": "~(으)ㄴ (past participle modifier)", "exp": "Modifies a noun with a past participle form to describe when/how the action occurred.", "example_in_sentence": "찍은 사진"}], "analysis": []}, {"text": "이 사진은 살아있는 동물을 찍은 가장 오래된 사진이라고 해요.", "translation": "This photograph is said to be the oldest photograph of a living animal ever taken.", "vocab": [{"ko": "살아있다", "en": "to be alive, to be living", "note": "Describes state of being alive; 살아있는 동물 = living animal"}, {"ko": "오래되다", "en": "to be old (in age/time)", "note": "State verb describing age; 가장 오래된 = the oldest"}], "grammar": [{"pattern": "~(으)ㄴ (past participle modifier)", "exp": "Modifies a noun with a past participle form to describe when/how the action occurred.", "example_in_sentence": "찍은 가장 오래된 사진"}, {"pattern": "~ㄴ다고 하다 (reported speech)", "exp": "Reports what someone says or claims about something.", "example_in_sentence": "가장 오래된 사진이라고 해요"}], "analysis": []}, {"text": "지금으로부터 180년도 더 전에 찍힌 거예요.", "translation": "It was taken more than 180 years ago.", "vocab": [{"ko": "지금", "en": "now (지금으로부터 = counting from now)", "note": "Time expression indicating the reference point is the present moment"}], "grammar": [{"pattern": "~(으)ㄴ (past participle modifier)", "exp": "Modifies a noun with a past participle form to describe when/how the action occurred.", "example_in_sentence": "찍힌 거"}], "analysis": []}, {"text": "사진을 찍은 사람은 프랑스 사람이에요.", "translation": "The person who took the photograph is French.", "vocab": [{"ko": "프랑스 사람", "en": "French person", "note": "Nationality descriptor; 프랑스 = France"}], "grammar": [{"pattern": "~(은)ㄴ (past participle modifier)", "exp": "Modifies a noun with a past participle form to describe when/how the action occurred.", "example_in_sentence": "찍은 사람"}], "analysis": []}, {"text": "이름이 아주 길어서 기억하기 어려워요.", "translation": "His name is very long and difficult to remember.", "vocab": [{"ko": "기억하다", "en": "to remember, to memorize", "note": "Action verb; 기억하기 어렵다 = difficult to remember"}], "grammar": [{"pattern": "~기 (nominalizing suffix)", "exp": "Converts a verb into a noun form, often used with adjectives like 어렵다 or 쉽다.", "example_in_sentence": "기억하기 어려워요"}], "analysis": []}, {"text": "그 시대에는 사진을 찍기가 정말 어려웠어요.", "translation": "Taking photographs in that era was really difficult.", "vocab": [{"ko": "시대", "en": "era, age, period", "note": "Noun describing a historical time period"}], "grammar": [{"pattern": "~기 (nominalizing suffix)", "exp": "Converts a verb into a noun form, often used with adjectives like 어렵다 or 쉽다.", "example_in_sentence": "사진을 찍기가 정말 어려웠어요"}], "analysis": []}, {"text": "지금처럼 쉽게 찍을 수 없었거든요.", "translation": "It was not possible to take them as easily as we do now.", "vocab": [{"ko": "쉽다", "en": "to be easy", "note": "Descriptive verb; opposite of 어렵다"}], "grammar": [{"pattern": "~(으)ㄹ 수 없다 (negative possibility)", "exp": "Expresses inability or impossibility to perform an action.", "example_in_sentence": "쉽게 찍을 수 없었거든요"}], "analysis": []}, {"text": "그래서 이 사진이 더욱 소중해요.", "translation": "That is why this photograph is even more precious.", "vocab": [{"ko": "소중하다", "en": "to be precious, to be valuable", "note": "Descriptive verb expressing worth or importance"}, {"ko": "더욱", "en": "even more, all the more", "note": "Adverb intensifying the following adjective"}], "grammar": [], "analysis": []}]}', vocab = '[{"ko": "찍히다", "en": "to be taken (passive of 찍다)", "note": "Used for photos/pictures being taken; passive voice"}, {"ko": "특별하다", "en": "to be special", "note": "Descriptive verb; 특별한 = special (modifying noun)"}, {"ko": "소", "en": "cow", "note": "Common noun; 한 마리 = one animal (counter)"}, {"ko": "살아있다", "en": "to be alive, to be living", "note": "Describes state of being alive; 살아있는 동물 = living animal"}, {"ko": "오래되다", "en": "to be old (in age/time)", "note": "State verb describing age; 가장 오래된 = the oldest"}, {"ko": "지금", "en": "now (지금으로부터 = counting from now)", "note": "Time expression indicating the reference point is the present moment"}, {"ko": "프랑스 사람", "en": "French person", "note": "Nationality descriptor; 프랑스 = France"}, {"ko": "기억하다", "en": "to remember, to memorize", "note": "Action verb; 기억하기 어렵다 = difficult to remember"}, {"ko": "시대", "en": "era, age, period", "note": "Noun describing a historical time period"}, {"ko": "쉽다", "en": "to be easy", "note": "Descriptive verb; opposite of 어렵다"}, {"ko": "소중하다", "en": "to be precious, to be valuable", "note": "Descriptive verb expressing worth or importance"}, {"ko": "더욱", "en": "even more, all the more", "note": "Adverb intensifying the following adjective"}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'mot9r8iatw6l' and md5(translation) = 'ad38b712c6ea18b7c16c5ce28759e7ed';
update public.article_cache set translation = '{"texts": ["There is a special fence between Germany and Denmark. This fence was not built to stop people. It was built to block wild boars.", "Wild boars are animals that destroy crops. They can also transmit dangerous diseases to people. That is why the two countries built the fence together.", "This fence is about 70 kilometers long. Its height is approximately 1.5 meters. It is also buried about 50 centimeters deep underground.", "South Korea also has many concerns due to wild boars. Farmers are suffering significant damage. Germany and Denmark''s method could serve as a good example for us."], "sentences": [{"text": "독일과 덴마크 사이에 특별한 담장이 있어요.", "translation": "There is a special fence between Germany and Denmark.", "vocab": [{"ko": "담장", "en": "fence", "note": ""}, {"ko": "사이", "en": "between; space in the middle", "note": ""}], "grammar": [], "analysis": []}, {"text": "이 담장은 사람을 막으려고 만든 것이 아니에요.", "translation": "This fence was not built to stop people.", "vocab": [{"ko": "막다", "en": "to block; to stop", "note": ""}], "grammar": [{"pattern": "~으려고 만들다", "exp": "Expresses purpose: ''was made in order to / for the purpose of''.", "example_in_sentence": "사람을 막으려고 만든 것"}, {"pattern": "~ㄴ 것이 아니다", "exp": "Negates an assumption or claim: ''it is not the case that''.", "example_in_sentence": "사람을 막으려고 만든 것이 아니에요"}], "analysis": []}, {"text": "멧돼지를 막으려고 만들었어요.", "translation": "It was built to block wild boars.", "vocab": [{"ko": "멧돼지", "en": "wild boar", "note": ""}], "grammar": [{"pattern": "~으려고 만들다", "exp": "Expresses purpose: ''was made in order to / for the purpose of''.", "example_in_sentence": "멧돼지를 막으려고 만들었어요"}], "analysis": []}, {"text": "멧돼지는 농작물을 망가뜨리는 동물이에요.", "translation": "Wild boars are animals that destroy crops.", "vocab": [{"ko": "농작물", "en": "crops; agricultural products", "note": ""}, {"ko": "망가뜨리다", "en": "to damage; to ruin", "note": ""}], "grammar": [{"pattern": "~ㄴ 동물", "exp": "Past tense modifier: describes the type or characteristic of the noun it precedes.", "example_in_sentence": "농작물을 망가뜨리는 동물"}], "analysis": []}, {"text": "또 사람에게 위험한 병을 옮길 수도 있어요.", "translation": "They can also transmit dangerous diseases to people.", "vocab": [{"ko": "위험하다", "en": "to be dangerous", "note": ""}, {"ko": "병", "en": "disease; illness", "note": ""}, {"ko": "옮기다", "en": "to transmit; to pass on; to move", "note": ""}], "grammar": [{"pattern": "~을 수도 있다", "exp": "Expresses possibility: ''can / it is possible to''.", "example_in_sentence": "병을 옮길 수도 있어요"}], "analysis": []}, {"text": "그래서 두 나라가 함께 담장을 세웠어요.", "translation": "That is why the two countries built the fence together.", "vocab": [{"ko": "함께", "en": "together", "note": ""}, {"ko": "세우다", "en": "to build; to erect; to set up", "note": "Different from 짓다; often used for structures, systems, or plans."}], "grammar": [{"pattern": "그래서", "exp": "Connective: ''that is why; therefore'' — shows causal relationship with the previous sentence.", "example_in_sentence": "그래서 두 나라가 함께 담장을 세웠어요"}], "analysis": []}, {"text": "이 담장은 약 70킬로미터나 길어요.", "translation": "This fence is about 70 kilometers long.", "vocab": [{"ko": "길다", "en": "to be long", "note": "Adjective for length or duration."}], "grammar": [{"pattern": "~나", "exp": "Particle for approximation: ''about; as much as''.", "example_in_sentence": "약 70킬로미터나 길어요"}], "analysis": []}, {"text": "높이는 1.5미터 정도예요.", "translation": "Its height is approximately 1.5 meters.", "vocab": [{"ko": "높이", "en": "height", "note": ""}], "grammar": [{"pattern": "~정도", "exp": "Expresses approximation or rough extent: ''about; roughly; around''.", "example_in_sentence": "1.5미터 정도예요"}], "analysis": []}, {"text": "땅 아래로도 50센티미터 깊이로 묻혀 있어요.", "translation": "It is also buried about 50 centimeters deep underground.", "vocab": [{"ko": "깊이", "en": "depth", "note": ""}, {"ko": "묻히다", "en": "to be buried", "note": ""}], "grammar": [{"pattern": "~어/아 있다", "exp": "Indicates a state or condition that results from a completed action: ''is buried''.", "example_in_sentence": "묻혀 있어요"}], "analysis": []}, {"text": "한국에서도 멧돼지 때문에 고민이 많아요.", "translation": "South Korea also has many concerns due to wild boars.", "vocab": [{"ko": "때문에", "en": "because of; due to", "note": ""}, {"ko": "고민", "en": "worry; concern; trouble", "note": ""}], "grammar": [{"pattern": "~때문에", "exp": "Shows cause or reason: ''because of; due to''.", "example_in_sentence": "멧돼지 때문에"}], "analysis": []}, {"text": "농민들이 피해를 많이 받고 있어요.", "translation": "Farmers are suffering significant damage.", "vocab": [{"ko": "농민", "en": "farmer", "note": ""}, {"ko": "피해", "en": "damage; harm; loss", "note": ""}], "grammar": [{"pattern": "~고 있다", "exp": "Indicates ongoing or progressive action: ''are receiving / are suffering''.", "example_in_sentence": "피해를 많이 받고 있어요"}], "analysis": []}, {"text": "독일과 덴마크의 방법이 좋은 예가 될 수 있을 것 같아요.", "translation": "Germany and Denmark''s method could serve as a good example for us.", "vocab": [{"ko": "방법", "en": "method; way; approach", "note": ""}, {"ko": "예", "en": "example; instance", "note": ""}], "grammar": [{"pattern": "~ㄹ 수 있다", "exp": "Expresses possibility or potential: ''can / could; is able to''.", "example_in_sentence": "좋은 예가 될 수 있을"}, {"pattern": "~ㄴ 것 같다", "exp": "Expresses supposition or likelihood: ''seems like; appears to; it seems that''.", "example_in_sentence": "될 수 있을 것 같아요"}], "analysis": []}]}', vocab = '[{"ko": "담장", "en": "fence", "note": ""}, {"ko": "사이", "en": "between; space in the middle", "note": ""}, {"ko": "막다", "en": "to block; to stop", "note": ""}, {"ko": "멧돼지", "en": "wild boar", "note": ""}, {"ko": "농작물", "en": "crops; agricultural products", "note": ""}, {"ko": "망가뜨리다", "en": "to damage; to ruin", "note": ""}, {"ko": "위험하다", "en": "to be dangerous", "note": ""}, {"ko": "병", "en": "disease; illness", "note": ""}, {"ko": "옮기다", "en": "to transmit; to pass on; to move", "note": ""}, {"ko": "함께", "en": "together", "note": ""}, {"ko": "세우다", "en": "to build; to erect; to set up", "note": "Different from 짓다; often used for structures, systems, or plans."}, {"ko": "길다", "en": "to be long", "note": "Adjective for length or duration."}, {"ko": "높이", "en": "height", "note": ""}, {"ko": "깊이", "en": "depth", "note": ""}, {"ko": "묻히다", "en": "to be buried", "note": ""}, {"ko": "때문에", "en": "because of; due to", "note": ""}, {"ko": "고민", "en": "worry; concern; trouble", "note": ""}, {"ko": "농민", "en": "farmer", "note": ""}, {"ko": "피해", "en": "damage; harm; loss", "note": ""}, {"ko": "방법", "en": "method; way; approach", "note": ""}, {"ko": "예", "en": "example; instance", "note": ""}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'mot9sym9w8vr' and md5(translation) = '7ba2b3fe1c54289953d7bb66874ec278';
update public.article_cache set translation = '{"texts": ["The Snow Leopard is one of the most athletic animals in the world. They can jump up to 15 meters at a time.", "This is a distance similar to the height of a 5-story building. Compared to the world record for human long jump, which is about 9 meters, this is truly an amazing ability.", "Snow leopards live in high mountains in the Himalayas and Central Asia. They developed this jumping ability to hunt in harsh, rocky mountains.", "A long tail and strong hind legs help maintain balance when jumping. Thick fur and wide toes help them live in cold mountainous regions.", "Currently, snow leopards are endangered. It is said that only about 4,000 remain in the world."], "sentences": [{"text": "눈표범(Snow Leopard)은 세계에서 가장 운동 능력이 뛰어난 동물 중 하나예요.", "translation": "The snow leopard is one of the most athletically gifted animals in the world.", "vocab": [{"ko": "운동 능력", "en": "athletic ability; physical capability"}, {"ko": "뛰어나다", "en": "to excel; to be outstanding"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Lets an adjective describe a noun. 뛰어나다 → 뛰어난 동물 = an outstanding animal.", "example_in_sentence": "뛰어난 동물"}, {"type": "expression", "label": "~중 하나", "exp": "Indicates ''one of [plural set]''; selects one member from a group of multiple entities.", "example_in_sentence": "동물 중 하나"}]}, {"text": "이들은 한 번에 최대 15미터까지 점프할 수 있어요.", "translation": "They can jump up to a maximum of 15 meters in a single leap.", "vocab": [{"ko": "한 번에", "en": "in one go; at one time"}, {"ko": "최대", "en": "maximum"}, {"ko": "점프하다", "en": "to jump"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can / be able to''. 점프하다 → 점프할 수 있어요 = can jump.", "example_in_sentence": "점프할 수 있어요"}]}, {"text": "이는 일반 건물 5층 높이와 비슷한 거리예요.", "translation": "This is a distance similar to the height of a typical five-story building.", "vocab": [{"ko": "일반", "en": "general; typical; ordinary"}, {"ko": "층", "en": "floor; story (of a building)"}, {"ko": "높이", "en": "height"}], "analysis": [{"type": "grammar", "label": "~와/과 비슷하다", "exp": "Means ''to be similar to ~''. 높이와 비슷한 거리 = a distance similar to the height.", "example_in_sentence": "높이와 비슷한 거리"}]}, {"text": "사람이 멀리뛰기 세계 기록이 약 9미터인 것과 비교하면 정말 놀라운 능력이에요.", "translation": "Compared to the human world record for long jump, which is about 9 meters, this is truly a remarkable ability.", "vocab": [{"ko": "멀리뛰기", "en": "long jump"}, {"ko": "세계 기록", "en": "world record"}, {"ko": "비교하다", "en": "to compare"}, {"ko": "놀랍다", "en": "to be surprising; to be remarkable"}], "analysis": [{"type": "expression", "label": "~와/과 비교하면", "exp": "Means ''compared to ~''. 비교하다 → 비교하면 = if (you) compare. 9미터인 것과 비교하면 = compared to (the record) being 9 m.", "example_in_sentence": "9미터인 것과 비교하면"}, {"type": "grammar", "label": "~인 것", "exp": "Turns ''is N'' into a noun phrase. 9미터이다 → 9미터인 것 = (the fact of) being 9 meters.", "example_in_sentence": "9미터인 것"}]}, {"text": "눈표범은 히말라야와 중앙아시아의 높은 산에서 살아요.", "translation": "Snow leopards live in high mountains of the Himalayas and Central Asia.", "vocab": [{"ko": "히말라야", "en": "Himalayas"}, {"ko": "중앙아시아", "en": "Central Asia"}], "analysis": []}, {"text": "험한 바위산에서 사냥하기 위해 이런 점프 능력을 발달시켰어요.", "translation": "In order to hunt in harsh rocky mountains, they developed such jumping abilities.", "vocab": [{"ko": "험하다", "en": "to be steep; harsh; rugged"}, {"ko": "바위산", "en": "rocky mountain"}, {"ko": "사냥하다", "en": "to hunt"}, {"ko": "발달시키다", "en": "to develop"}], "analysis": [{"type": "grammar", "label": "~기 위해", "exp": "Means ''in order to ~''. 사냥하다 → 사냥하기 위해 = in order to hunt.", "example_in_sentence": "사냥하기 위해"}]}, {"text": "긴 꼬리와 강한 뒷다리가 점프할 때 균형을 잡아줘요.", "translation": "The long tail and strong hind legs help maintain balance when jumping.", "vocab": [{"ko": "꼬리", "en": "tail"}, {"ko": "뒷다리", "en": "hind leg; back leg"}, {"ko": "균형", "en": "balance"}, {"ko": "잡다", "en": "to hold; (균형을 잡다) to keep balance"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 때", "exp": "Means ''when ~''. 점프하다 → 점프할 때 = when jumping.", "example_in_sentence": "점프할 때"}, {"type": "expression", "label": "~아/어주다", "exp": "Auxiliary verb expressing benefit to third party or expressing action done ''for'' someone. Here: ''help by doing''.", "example_in_sentence": "잡아줘요"}]}, {"text": "두꺼운 털과 넓은 발가락은 추운 산악 지역에서 생활하는 데 도움이 돼요.", "translation": "The thick fur and wide toes help with living in cold mountainous regions.", "vocab": [{"ko": "두껍다", "en": "to be thick"}, {"ko": "털", "en": "fur; hair"}, {"ko": "넓다", "en": "to be wide; to be broad"}, {"ko": "발가락", "en": "toe"}], "analysis": [{"type": "grammar", "label": "~는 데 도움이 되다", "exp": "Means ''to help in doing ~''. 생활하다 → 생활하는 데 도움이 돼요 = helps with living.", "example_in_sentence": "생활하는 데 도움이 돼요"}]}, {"text": "현재 눈표범은 멸종 위기에 처해 있어요.", "translation": "Currently, snow leopards are facing extinction.", "vocab": [{"ko": "현재", "en": "currently; at present"}, {"ko": "멸종", "en": "extinction"}, {"ko": "위기", "en": "crisis; danger"}], "analysis": [{"type": "expression", "label": "~에 처해 있다", "exp": "Means ''to be in (a difficult situation)''. 멸종 위기에 처해 있어요 = is facing extinction.", "example_in_sentence": "멸종 위기에 처해 있어요"}]}, {"text": "전 세계에 약 4천 마리만 남아 있다고 해요.", "translation": "They say only about 4,000 individuals remain in the entire world.", "vocab": [{"ko": "전 세계", "en": "whole world; entire globe"}, {"ko": "마리", "en": "classifier for animals"}, {"ko": "남다", "en": "to remain; to be left"}], "analysis": [{"type": "grammar", "label": "~만", "exp": "Particle marking exclusivity or limitation; ''only, merely''. Attaches to noun phrase.", "example_in_sentence": "4천 마리만"}, {"type": "expression", "label": "~다고 해요", "exp": "Hearsay or reported speech marker; ''they say that, it is said that''. Uses ~다고 + 하다 in present tense.", "example_in_sentence": "남아 있다고 해요"}]}], "version": "s6"}', vocab = '[{"ko": "운동 능력", "en": "athletic ability; physical capability", "note": ""}, {"ko": "뛰어나다", "en": "to excel; to be outstanding", "note": ""}, {"ko": "한 번에", "en": "in one go; at one time", "note": ""}, {"ko": "최대", "en": "maximum", "note": ""}, {"ko": "점프하다", "en": "to jump", "note": ""}, {"ko": "일반", "en": "general; typical; ordinary", "note": ""}, {"ko": "층", "en": "floor; story (of a building)", "note": ""}, {"ko": "높이", "en": "height", "note": ""}, {"ko": "멀리뛰기", "en": "long jump", "note": ""}, {"ko": "세계 기록", "en": "world record", "note": ""}, {"ko": "비교하다", "en": "to compare", "note": ""}, {"ko": "놀랍다", "en": "to be surprising; to be remarkable", "note": ""}, {"ko": "히말라야", "en": "Himalayas", "note": ""}, {"ko": "중앙아시아", "en": "Central Asia", "note": ""}, {"ko": "험하다", "en": "to be steep; harsh; rugged", "note": ""}, {"ko": "바위산", "en": "rocky mountain", "note": ""}, {"ko": "사냥하다", "en": "to hunt", "note": ""}, {"ko": "발달시키다", "en": "to develop", "note": ""}, {"ko": "꼬리", "en": "tail", "note": ""}, {"ko": "뒷다리", "en": "hind leg; back leg", "note": ""}, {"ko": "균형", "en": "balance", "note": ""}, {"ko": "잡다", "en": "to hold; (균형을 잡다) to keep balance", "note": ""}, {"ko": "두껍다", "en": "to be thick", "note": ""}, {"ko": "털", "en": "fur; hair", "note": ""}, {"ko": "넓다", "en": "to be wide; to be broad", "note": ""}, {"ko": "발가락", "en": "toe", "note": ""}, {"ko": "현재", "en": "currently; at present", "note": ""}, {"ko": "멸종", "en": "extinction", "note": ""}, {"ko": "위기", "en": "crisis; danger", "note": ""}, {"ko": "전 세계", "en": "whole world; entire globe", "note": ""}, {"ko": "마리", "en": "classifier for animals", "note": ""}, {"ko": "남다", "en": "to remain; to be left", "note": ""}, {"word": "눈표범", "reading": "nun-pyobbeom", "meaning": "snow leopard (a large wild cat native to Central Asian mountains)", "context": "눈표범(Snow Leopard)은 세계에서 가장 운동 능력이 뛰어난"}, {"word": "균형을 잡다", "reading": "gyun-hyeong-eul jap-da", "meaning": "to maintain balance; to keep equilibrium", "context": "강한 뒷다리가 점프할 때 균형을 잡아줘요"}, {"word": "멸종 위기", "reading": "myeol-jong wi-gi", "meaning": "endangered status; threat of extinction", "context": "현재 눈표범은 멸종 위기에 처해 있어요"}]', grammar = '{"patterns": [{"name": "~(으)ㄴ (adjective modifier)", "level": "Intermediate", "exp": "Lets an adjective describe a noun. 뛰어나다 → 뛰어난 동물 = an outstanding animal.", "ex_ko": "눈표범(Snow Leopard)은 세계에서 가장 운동 능력이 뛰어난 동물 중 하나예요.", "ex_en": "The snow leopard is one of the most athletically gifted animals in the world."}, {"name": "~(으)ㄹ 수 있다", "level": "Intermediate", "exp": "Means ''can / be able to''. 점프하다 → 점프할 수 있어요 = can jump.", "ex_ko": "이들은 한 번에 최대 15미터까지 점프할 수 있어요.", "ex_en": "They can jump up to a maximum of 15 meters in a single leap."}, {"name": "~와/과 비슷하다", "level": "Intermediate", "exp": "Means ''to be similar to ~''. 높이와 비슷한 거리 = a distance similar to the height.", "ex_ko": "이는 일반 건물 5층 높이와 비슷한 거리예요.", "ex_en": "This is a distance similar to the height of a typical five-story building."}, {"name": "~인 것", "level": "Intermediate", "exp": "Turns ''is N'' into a noun phrase. 9미터이다 → 9미터인 것 = (the fact of) being 9 meters.", "ex_ko": "사람이 멀리뛰기 세계 기록이 약 9미터인 것과 비교하면 정말 놀라운 능력이에요.", "ex_en": "Compared to the human world record for long jump, which is about 9 meters, this is truly a remarkable ability."}, {"name": "~기 위해", "level": "Intermediate", "exp": "Means ''in order to ~''. 사냥하다 → 사냥하기 위해 = in order to hunt.", "ex_ko": "험한 바위산에서 사냥하기 위해 이런 점프 능력을 발달시켰어요.", "ex_en": "In order to hunt in harsh rocky mountains, they developed such jumping abilities."}, {"name": "~(으)ㄹ 때", "level": "Intermediate", "exp": "Means ''when ~''. 점프하다 → 점프할 때 = when jumping.", "ex_ko": "긴 꼬리와 강한 뒷다리가 점프할 때 균형을 잡아줘요.", "ex_en": "The long tail and strong hind legs help maintain balance when jumping."}, {"name": "~는 데 도움이 되다", "level": "Intermediate", "exp": "Means ''to help in doing ~''. 생활하다 → 생활하는 데 도움이 돼요 = helps with living.", "ex_ko": "두꺼운 털과 넓은 발가락은 추운 산악 지역에서 생활하는 데 도움이 돼요.", "ex_en": "The thick fur and wide toes help with living in cold mountainous regions."}, {"name": "~만", "level": "Intermediate", "exp": "Particle marking exclusivity or limitation; ''only, merely''. Attaches to noun phrase.", "ex_ko": "전 세계에 약 4천 마리만 남아 있다고 해요.", "ex_en": "They say only about 4,000 individuals remain in the entire world."}]}', updated_at = now() where article_id = 'movabeunv1hn' and md5(translation) = '38f2bcfda07ef7365b8db0531e8e47fe';
update public.article_cache set translation = '{"texts": ["What happens when a frog eats something poisonous? Unlike humans, it cannot vomit. Instead, it uses a truly amazing method.", "Frogs pull out their entire stomach outside their body. Then they clean the stomach thoroughly. When the cleaning is done, they put the stomach back inside their body.", "This method is called stomach eversion. It is a special survival method unique to frogs. Isn''t it really amazing?", "We can see frogs in Korean ponds and rice fields too. Even small frogs have this amazing ability."], "sentences": [{"text": "개구리가 독이 있는 것을 먹으면 어떻게 될까요?", "translation": "What happens if a frog eats something poisonous?", "vocab": [{"ko": "개구리", "en": "frog"}, {"ko": "독", "en": "poison"}, {"ko": "먹다", "en": "to eat"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "Means ''if'' or ''when''. 먹다 → 먹으면 (if it eats).", "example_in_sentence": "먹으면"}, {"type": "grammar", "label": "~(으)ㄹ까요", "exp": "Question ending used when wondering about something. 되다 → 될까요? (what will happen?)", "example_in_sentence": "될까요"}]}, {"text": "사람처럼 토를 하지 못해요.", "translation": "Unlike humans, (they) cannot vomit.", "vocab": [{"ko": "사람", "en": "person; human"}, {"ko": "토", "en": "vomit"}, {"ko": "하다", "en": "to do"}], "analysis": [{"type": "grammar", "label": "~처럼", "exp": "Postposition meaning ''like'' or ''as''. Marks similarity or manner.", "example_in_sentence": "사람처럼"}, {"type": "grammar", "label": "~지 못하다", "exp": "Negation form meaning ''cannot'' or ''unable to''. Emphasizes inability more than simple negation.", "example_in_sentence": "하지 못해요"}]}, {"text": "대신 정말 놀라운 방법을 사용해요.", "translation": "Instead, (they) use a truly amazing method.", "vocab": [{"ko": "대신", "en": "instead"}, {"ko": "놀랍다", "en": "to be amazing; surprising"}, {"ko": "방법", "en": "method; way"}, {"ko": "사용하다", "en": "to use"}], "analysis": [{"type": "grammar", "label": "ㅂ irregular + ~(으)ㄴ", "exp": "Adjective form used before a noun. 놀랍다 → 놀라운 (ㅂ changes to 우) = amazing.", "example_in_sentence": "놀라운 방법"}]}, {"text": "개구리는 위 전체를 몸 밖으로 꺼내요.", "translation": "Frogs pull out their entire stomach outside their body.", "vocab": [{"ko": "위", "en": "stomach"}, {"ko": "전체", "en": "whole; entire"}, {"ko": "몸", "en": "body"}, {"ko": "꺼내다", "en": "to pull out; to take out"}], "analysis": [{"type": "grammar", "label": "~(으)로", "exp": "Particle showing direction. 밖 (outside) + 으로 = to the outside. 몸 밖으로 = out of the body.", "example_in_sentence": "몸 밖으로"}]}, {"text": "그리고 위를 깨끗하게 청소해요.", "translation": "And (they) clean their stomach thoroughly.", "vocab": [{"ko": "깨끗하다", "en": "to be clean"}, {"ko": "청소하다", "en": "to clean"}], "analysis": [{"type": "grammar", "label": "~게", "exp": "Turns an adjective into an adverb. 깨끗하다 → 깨끗하게 (cleanly; thoroughly).", "example_in_sentence": "깨끗하게"}]}, {"text": "청소가 끝나면 위를 다시 몸 안으로 넣어요.", "translation": "When cleaning is finished, (they) put the stomach back inside their body again.", "vocab": [{"ko": "청소", "en": "cleaning"}, {"ko": "끝나다", "en": "to finish; to end"}, {"ko": "다시", "en": "again"}, {"ko": "안", "en": "inside"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "Means ''when'' or ''if''. 끝나다 → 끝나면 (when it is finished).", "example_in_sentence": "끝나면"}, {"type": "grammar", "label": "~(으)로", "exp": "Particle showing direction. 안 (inside) + 으로 = into. 몸 안으로 = back into the body.", "example_in_sentence": "몸 안으로"}]}, {"text": "이런 방법을 위 뒤집기라고 불러요.", "translation": "This method is called stomach eversion.", "vocab": [{"ko": "방법", "en": "method"}, {"ko": "뒤집다", "en": "to turn inside out; to flip"}, {"ko": "부르다", "en": "to call; to name"}], "analysis": [{"type": "grammar", "label": "~라고 부르다", "exp": "Expression meaning ''to call something ~'' or ''to refer to as''. Used for naming or labeling.", "example_in_sentence": "위 뒤집기라고 불러요"}]}, {"text": "개구리만의 특별한 생존 방법이에요.", "translation": "It is a survival method unique to frogs.", "vocab": [{"ko": "개구리", "en": "frog"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "생존", "en": "survival"}, {"ko": "방법", "en": "method"}], "analysis": [{"type": "grammar", "label": "~만의", "exp": "만 (only) + 의 (of) = belonging only to. 개구리만의 = unique to frogs.", "example_in_sentence": "개구리만의"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Adjective form used before a noun. 특별하다 → 특별한 (special).", "example_in_sentence": "특별한 생존 방법"}]}, {"text": "정말 신기하지 않나요?", "translation": "Isn''t it really fascinating?", "vocab": [{"ko": "정말", "en": "really; truly"}, {"ko": "신기하다", "en": "to be fascinating; to be amazing"}], "analysis": [{"type": "grammar", "label": "~지 않다", "exp": "Negation form. Combined with question ending creates rhetorical question expecting agreement.", "example_in_sentence": "신기하지"}, {"type": "grammar", "label": "~나요", "exp": "Soft, polite question ending. 않다 → 않나요? With ~지 않다 it means ''Isn''t it…?''", "example_in_sentence": "않나요"}]}, {"text": "우리나라 연못이나 논에서도 개구리를 볼 수 있어요.", "translation": "You can also see frogs in ponds or rice paddies in our country.", "vocab": [{"ko": "우리나라", "en": "our country"}, {"ko": "연못", "en": "pond"}, {"ko": "논", "en": "rice paddy"}, {"ko": "보다", "en": "to see"}], "analysis": [{"type": "grammar", "label": "~이나", "exp": "Particle meaning ''or'' offering alternatives. Lists multiple locations.", "example_in_sentence": "연못이나 논"}, {"type": "grammar", "label": "~에서도", "exp": "Postposition with additive particle. Means ''also in'' or ''even in'', emphasizing inclusion.", "example_in_sentence": "논에서도"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can'' or ''be able to''. 보다 → 볼 수 있어요 (can see).", "example_in_sentence": "볼 수 있어요"}]}, {"text": "작은 개구리도 이런 놀라운 능력이 있답니다.", "translation": "Even small frogs have this amazing ability.", "vocab": [{"ko": "작다", "en": "to be small"}, {"ko": "개구리", "en": "frog"}, {"ko": "능력", "en": "ability"}, {"ko": "있다", "en": "to have; to exist"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Additive particle meaning ''also'' or ''even''. Shows inclusion or emphasis.", "example_in_sentence": "작은 개구리도"}, {"type": "grammar", "label": "~답니다", "exp": "Friendly ending that tells the listener a fact, often used in stories. 있다 → 있답니다 (they have, you know).", "example_in_sentence": "있답니다"}]}], "version": "s6"}', vocab = '[{"ko": "개구리", "en": "frog", "note": ""}, {"ko": "독", "en": "poison", "note": ""}, {"ko": "먹다", "en": "to eat", "note": ""}, {"ko": "사람", "en": "person; human", "note": ""}, {"ko": "토", "en": "vomit", "note": ""}, {"ko": "하다", "en": "to do", "note": ""}, {"ko": "대신", "en": "instead", "note": ""}, {"ko": "놀랍다", "en": "to be amazing; surprising", "note": ""}, {"ko": "방법", "en": "method; way", "note": ""}, {"ko": "사용하다", "en": "to use", "note": ""}, {"ko": "위", "en": "stomach", "note": ""}, {"ko": "전체", "en": "whole; entire", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"ko": "꺼내다", "en": "to pull out; to take out", "note": ""}, {"ko": "깨끗하다", "en": "to be clean", "note": ""}, {"ko": "청소하다", "en": "to clean", "note": ""}, {"ko": "청소", "en": "cleaning", "note": ""}, {"ko": "끝나다", "en": "to finish; to end", "note": ""}, {"ko": "다시", "en": "again", "note": ""}, {"ko": "안", "en": "inside", "note": ""}, {"ko": "뒤집다", "en": "to turn inside out; to flip", "note": ""}, {"ko": "부르다", "en": "to call; to name", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "생존", "en": "survival", "note": ""}, {"ko": "정말", "en": "really; truly", "note": ""}, {"ko": "신기하다", "en": "to be fascinating; to be amazing", "note": ""}, {"ko": "우리나라", "en": "our country", "note": ""}, {"ko": "연못", "en": "pond", "note": ""}, {"ko": "논", "en": "rice paddy", "note": ""}, {"ko": "보다", "en": "to see", "note": ""}, {"ko": "작다", "en": "to be small", "note": ""}, {"ko": "능력", "en": "ability", "note": ""}, {"ko": "있다", "en": "to have; to exist", "note": ""}, {"word": "뒤집기", "reading": "dwijipgi", "meaning": "flipping; turning inside out", "context": "이런 방법을 위 뒤집기라고 불러요"}]', grammar = '{"patterns": [{"name": "~(으)면", "level": "Beginner", "exp": "Means ''when'' or ''if''. 끝나다 → 끝나면 (when it is finished).", "ex_ko": "개구리가 독이 있는 것을 먹으면 어떻게 될까요?", "ex_en": "What happens if a frog eats something poisonous?"}, {"name": "~(으)ㄹ까요", "level": "Beginner", "exp": "Question ending used when wondering about something. 되다 → 될까요? (what will happen?)", "ex_ko": "개구리가 독이 있는 것을 먹으면 어떻게 될까요?", "ex_en": "What happens if a frog eats something poisonous?"}, {"name": "~처럼", "level": "Beginner", "exp": "Postposition meaning ''like'' or ''as''. Marks similarity or manner.", "ex_ko": "사람처럼 토를 하지 못해요.", "ex_en": "Unlike humans, (they) cannot vomit."}, {"name": "~지 못하다", "level": "Beginner", "exp": "Negation form meaning ''cannot'' or ''unable to''. Emphasizes inability more than simple negation.", "ex_ko": "사람처럼 토를 하지 못해요.", "ex_en": "Unlike humans, (they) cannot vomit."}, {"name": "ㅂ irregular + ~(으)ㄴ", "level": "Beginner", "exp": "Adjective form used before a noun. 놀랍다 → 놀라운 (ㅂ changes to 우) = amazing.", "ex_ko": "대신 정말 놀라운 방법을 사용해요.", "ex_en": "Instead, (they) use a truly amazing method."}, {"name": "~(으)로", "level": "Beginner", "exp": "Particle showing direction. 밖 (outside) + 으로 = to the outside. 몸 밖으로 = out of the body.", "ex_ko": "개구리는 위 전체를 몸 밖으로 꺼내요.", "ex_en": "Frogs pull out their entire stomach outside their body."}, {"name": "~게", "level": "Beginner", "exp": "Turns an adjective into an adverb. 깨끗하다 → 깨끗하게 (cleanly; thoroughly).", "ex_ko": "그리고 위를 깨끗하게 청소해요.", "ex_en": "And (they) clean their stomach thoroughly."}, {"name": "~라고 부르다", "level": "Beginner", "exp": "Expression meaning ''to call something ~'' or ''to refer to as''. Used for naming or labeling.", "ex_ko": "이런 방법을 위 뒤집기라고 불러요.", "ex_en": "This method is called stomach eversion."}, {"name": "~만의", "level": "Beginner", "exp": "만 (only) + 의 (of) = belonging only to. 개구리만의 = unique to frogs.", "ex_ko": "개구리만의 특별한 생존 방법이에요.", "ex_en": "It is a survival method unique to frogs."}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Beginner", "exp": "Adjective form used before a noun. 특별하다 → 특별한 (special).", "ex_ko": "개구리만의 특별한 생존 방법이에요.", "ex_en": "It is a survival method unique to frogs."}, {"name": "~지 않다", "level": "Beginner", "exp": "Negation form. Combined with question ending creates rhetorical question expecting agreement.", "ex_ko": "정말 신기하지 않나요?", "ex_en": "Isn''t it really fascinating?"}, {"name": "~나요", "level": "Beginner", "exp": "Soft, polite question ending. 않다 → 않나요? With ~지 않다 it means ''Isn''t it…?''", "ex_ko": "정말 신기하지 않나요?", "ex_en": "Isn''t it really fascinating?"}, {"name": "~이나", "level": "Beginner", "exp": "Particle meaning ''or'' offering alternatives. Lists multiple locations.", "ex_ko": "우리나라 연못이나 논에서도 개구리를 볼 수 있어요.", "ex_en": "You can also see frogs in ponds or rice paddies in our country."}, {"name": "~에서도", "level": "Beginner", "exp": "Postposition with additive particle. Means ''also in'' or ''even in'', emphasizing inclusion.", "ex_ko": "우리나라 연못이나 논에서도 개구리를 볼 수 있어요.", "ex_en": "You can also see frogs in ponds or rice paddies in our country."}, {"name": "~(으)ㄹ 수 있다", "level": "Beginner", "exp": "Means ''can'' or ''be able to''. 보다 → 볼 수 있어요 (can see).", "ex_ko": "우리나라 연못이나 논에서도 개구리를 볼 수 있어요.", "ex_en": "You can also see frogs in ponds or rice paddies in our country."}]}', updated_at = now() where article_id = 'movac9qfgm93' and md5(translation) = 'dd299782490c9498d8d2444df379247b';
update public.article_cache set translation = '{"texts": ["A very special animal was discovered in Kenya. It is the only white giraffe in the world.", "Unlike regular giraffes, this giraffe''s entire body is white. Usually giraffes have brown spots, but this giraffe is completely white.", "Scientists say this giraffe is very rare. There is only one giraffe of this color on Earth.", "The Kenyan government is protecting this special giraffe. Many people are visiting Kenya to see this amazing animal."], "sentences": [{"text": "케냐에서 매우 특별한 동물이 발견됐어요.", "translation": "A very special animal was discovered in Kenya.", "vocab": [{"ko": "케냐", "en": "Kenya"}, {"ko": "매우", "en": "very"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "발견되다", "en": "to be discovered"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative particle marking the place where an action occurs. 케냐 + 에서 = in/at Kenya.", "example_in_sentence": "케냐에서"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 발견되다 → 발견되었어요 → 발견됐어요 (was discovered).", "example_in_sentence": "발견됐어요"}]}, {"text": "전 세계에서 유일한 흰색 기린이에요.", "translation": "It is the only white giraffe in the entire world.", "vocab": [{"ko": "전 세계", "en": "entire world"}, {"ko": "유일하다", "en": "to be only/unique"}, {"ko": "흰색", "en": "white color"}, {"ko": "기린", "en": "giraffe"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative particle marking scope or range. 전 세계 + 에서 = in/among the entire world.", "example_in_sentence": "전 세계에서"}, {"type": "grammar", "label": "~이에요", "exp": "Polite ''to be'' after a noun ending in a consonant. 기린 + 이에요 = is a giraffe.", "example_in_sentence": "기린이에요"}]}, {"text": "이 기린은 일반 기린과 다르게 온몸이 하얀색이에요.", "translation": "Unlike ordinary giraffes, this giraffe''s whole body is white.", "vocab": [{"ko": "일반", "en": "ordinary/general"}, {"ko": "다르다", "en": "to be different"}, {"ko": "온몸", "en": "whole body"}, {"ko": "하얀색", "en": "white color"}], "analysis": [{"type": "grammar", "label": "~와/과 다르게", "exp": "Means ''unlike'' or ''differently from''. 일반 기린과 다르게 = unlike ordinary giraffes.", "example_in_sentence": "일반 기린과 다르게"}, {"type": "grammar", "label": "~게", "exp": "Adverbializer turning adjectives into manner adverbs. 다르다 → 다르게 = differently.", "example_in_sentence": "다르게"}]}, {"text": "보통 기린은 갈색 점무늬가 있지만 이 기린은 완전히 흰색이에요.", "translation": "Ordinary giraffes have brown spots, but this giraffe is completely white.", "vocab": [{"ko": "보통", "en": "ordinary/usually"}, {"ko": "갈색", "en": "brown color"}, {"ko": "점무늬", "en": "spot/pattern"}, {"ko": "완전히", "en": "completely"}], "analysis": [{"type": "grammar", "label": "~지만", "exp": "Connective ending expressing contrast or concession between two clauses. 있지만 = ''have (but)''. Joins main clauses.", "example_in_sentence": "있지만"}, {"type": "grammar", "label": "~이에요", "exp": "Present copula. 흰색 + 이에요 = is white color.", "example_in_sentence": "흰색이에요"}]}, {"text": "과학자들은 이 기린이 매우 귀하다고 말해요.", "translation": "Scientists say that this giraffe is very rare.", "vocab": [{"ko": "과학자", "en": "scientist"}, {"ko": "귀하다", "en": "to be rare/precious"}, {"ko": "말하다", "en": "to say"}], "analysis": [{"type": "grammar", "label": "~다고 말하다", "exp": "Reports what someone says. 귀하다 → 귀하다고 말해요 (they say that it is rare).", "example_in_sentence": "귀하다고 말해요"}, {"type": "grammar", "label": "~어요", "exp": "Present tense ending for polite/spoken style. 말하다 → 말해요.", "example_in_sentence": "말해요"}]}, {"text": "이런 색깔의 기린은 지구상에 단 한 마리밖에 없어요.", "translation": "There is only one giraffe with this color on Earth.", "vocab": [{"ko": "색깔", "en": "color"}, {"ko": "지구상", "en": "on Earth"}, {"ko": "단", "en": "only/merely"}, {"ko": "마리", "en": "counter for animals"}], "analysis": [{"type": "grammar", "label": "~의", "exp": "Possessive/genitive particle marking attribution or relationship. 색깔 + 의 = ''of color'' or ''with color''.", "example_in_sentence": "색깔의"}, {"type": "grammar", "label": "~밖에 없다", "exp": "Means ''only''. 밖에 is always followed by a negative word. 한 마리밖에 없어요 = there is only one.", "example_in_sentence": "한 마리밖에 없어요"}]}, {"text": "케냐 정부는 이 특별한 기린을 보호하고 있어요.", "translation": "The Kenyan government is protecting this special giraffe.", "vocab": [{"ko": "정부", "en": "government"}, {"ko": "보호하다", "en": "to protect"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Progressive/continuous aspect. 보호하다 + ~고 있어요 = ''is protecting (ongoing action)''. Shows action in progress.", "example_in_sentence": "보호하고 있어요"}]}, {"text": "많은 사람들이 이 신기한 동물을 보기 위해 케냐를 방문하고 있어요.", "translation": "Many people are visiting Kenya to see this amazing animal.", "vocab": [{"ko": "많다", "en": "to be many"}, {"ko": "사람", "en": "person/people"}, {"ko": "신기하다", "en": "to be amazing/interesting"}, {"ko": "보다", "en": "to see"}], "analysis": [{"type": "grammar", "label": "~기 위해", "exp": "Shows purpose: ''in order to''. 보다 → 보기 위해 (in order to see).", "example_in_sentence": "보기 위해"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect. 방문하다 + ~고 있어요 = ''are visiting (ongoing action)''.", "example_in_sentence": "방문하고 있어요"}]}], "version": "s6"}', vocab = '[{"ko": "케냐", "en": "Kenya", "note": ""}, {"ko": "매우", "en": "very", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "발견되다", "en": "to be discovered", "note": ""}, {"ko": "전 세계", "en": "entire world", "note": ""}, {"ko": "유일하다", "en": "to be only/unique", "note": ""}, {"ko": "흰색", "en": "white color", "note": ""}, {"ko": "기린", "en": "giraffe", "note": ""}, {"ko": "일반", "en": "ordinary/general", "note": ""}, {"ko": "다르다", "en": "to be different", "note": ""}, {"ko": "온몸", "en": "whole body", "note": ""}, {"ko": "하얀색", "en": "white color", "note": ""}, {"ko": "보통", "en": "ordinary/usually", "note": ""}, {"ko": "갈색", "en": "brown color", "note": ""}, {"ko": "점무늬", "en": "spot/pattern", "note": ""}, {"ko": "완전히", "en": "completely", "note": ""}, {"ko": "과학자", "en": "scientist", "note": ""}, {"ko": "귀하다", "en": "to be rare/precious", "note": ""}, {"ko": "말하다", "en": "to say", "note": ""}, {"ko": "색깔", "en": "color", "note": ""}, {"ko": "지구상", "en": "on Earth", "note": ""}, {"ko": "단", "en": "only/merely", "note": ""}, {"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "정부", "en": "government", "note": ""}, {"ko": "보호하다", "en": "to protect", "note": ""}, {"ko": "많다", "en": "to be many", "note": ""}, {"ko": "사람", "en": "person/people", "note": ""}, {"ko": "신기하다", "en": "to be amazing/interesting", "note": ""}, {"ko": "보다", "en": "to see", "note": ""}, {"word": "방문하다", "reading": "bangmunhada", "meaning": "to visit", "context": "많은 사람들이 이 신기한 동물을 보기 위해 케냐를 방문하고 있어요"}]', grammar = '{"patterns": [{"name": "~에서", "level": "Beginner", "exp": "Locative particle marking the place where an action occurs. 케냐 + 에서 = in/at Kenya.", "ex_ko": "케냐에서 매우 특별한 동물이 발견됐어요.", "ex_en": "A very special animal was discovered in Kenya."}, {"name": "~았/었어요", "level": "Beginner", "exp": "Past tense polite ending. 발견되다 → 발견되었어요 → 발견됐어요 (was discovered).", "ex_ko": "케냐에서 매우 특별한 동물이 발견됐어요.", "ex_en": "A very special animal was discovered in Kenya."}, {"name": "~이에요", "level": "Beginner", "exp": "Polite ''to be'' after a noun ending in a consonant. 기린 + 이에요 = is a giraffe.", "ex_ko": "전 세계에서 유일한 흰색 기린이에요.", "ex_en": "It is the only white giraffe in the entire world."}, {"name": "~와/과 다르게", "level": "Beginner", "exp": "Means ''unlike'' or ''differently from''. 일반 기린과 다르게 = unlike ordinary giraffes.", "ex_ko": "이 기린은 일반 기린과 다르게 온몸이 하얀색이에요.", "ex_en": "Unlike ordinary giraffes, this giraffe''s whole body is white."}, {"name": "~게", "level": "Beginner", "exp": "Adverbializer turning adjectives into manner adverbs. 다르다 → 다르게 = differently.", "ex_ko": "이 기린은 일반 기린과 다르게 온몸이 하얀색이에요.", "ex_en": "Unlike ordinary giraffes, this giraffe''s whole body is white."}, {"name": "~지만", "level": "Beginner", "exp": "Connective ending expressing contrast or concession between two clauses. 있지만 = ''have (but)''. Joins main clauses.", "ex_ko": "보통 기린은 갈색 점무늬가 있지만 이 기린은 완전히 흰색이에요.", "ex_en": "Ordinary giraffes have brown spots, but this giraffe is completely white."}, {"name": "~다고 말하다", "level": "Beginner", "exp": "Reports what someone says. 귀하다 → 귀하다고 말해요 (they say that it is rare).", "ex_ko": "과학자들은 이 기린이 매우 귀하다고 말해요.", "ex_en": "Scientists say that this giraffe is very rare."}, {"name": "~어요", "level": "Beginner", "exp": "Present tense ending for polite/spoken style. 말하다 → 말해요.", "ex_ko": "과학자들은 이 기린이 매우 귀하다고 말해요.", "ex_en": "Scientists say that this giraffe is very rare."}, {"name": "~의", "level": "Beginner", "exp": "Possessive/genitive particle marking attribution or relationship. 색깔 + 의 = ''of color'' or ''with color''.", "ex_ko": "이런 색깔의 기린은 지구상에 단 한 마리밖에 없어요.", "ex_en": "There is only one giraffe with this color on Earth."}, {"name": "~밖에 없다", "level": "Beginner", "exp": "Means ''only''. 밖에 is always followed by a negative word. 한 마리밖에 없어요 = there is only one.", "ex_ko": "이런 색깔의 기린은 지구상에 단 한 마리밖에 없어요.", "ex_en": "There is only one giraffe with this color on Earth."}, {"name": "~고 있다", "level": "Beginner", "exp": "Progressive/continuous aspect. 보호하다 + ~고 있어요 = ''is protecting (ongoing action)''. Shows action in progress.", "ex_ko": "케냐 정부는 이 특별한 기린을 보호하고 있어요.", "ex_en": "The Kenyan government is protecting this special giraffe."}, {"name": "~기 위해", "level": "Beginner", "exp": "Shows purpose: ''in order to''. 보다 → 보기 위해 (in order to see).", "ex_ko": "많은 사람들이 이 신기한 동물을 보기 위해 케냐를 방문하고 있어요.", "ex_en": "Many people are visiting Kenya to see this amazing animal."}]}', updated_at = now() where article_id = 'movad4941iq0' and md5(translation) = '2c9974d1e274090f6c4f14404a798ae2';
update public.article_cache set translation = '{"texts": ["Recently, scientists discovered a surprising fact. Large dinosaurs like the Tyrannosaurus (T-Rex) were able to swim.", "This discovery was possible because of claw marks left on stone. By looking at these marks found near rivers, scientists learned something. It is evidence that dinosaurs swam in water using their claws.", "Of course, dinosaurs'' swimming ability had limitations. It would have been difficult for them to go into deep places. However, they were able to swim in shallow water.", "This kind of discovery makes us think about dinosaurs in new ways. It shows that dinosaurs lived in more diverse environments than we thought."], "sentences": [{"text": "최근 과학자들이 놀라운 사실을 발견했어요.", "translation": "Recently, scientists discovered a surprising fact.", "vocab": [{"ko": "최근", "en": "recently"}, {"ko": "과학자", "en": "scientist"}, {"ko": "놀랍다", "en": "to be surprising; amazing"}, {"ko": "사실", "en": "fact"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending for statements. Marks completion of action: 발견하다 (discover) → 발견했어요 (discovered).", "example_in_sentence": "발견했어요"}]}, {"text": "티라노사우루스(T-Rex) 같은 큰 공룡들도 수영을 할 수 있었다는 거예요.", "translation": "It means that even large dinosaurs like Tyrannosaurus (T-Rex) were able to swim.", "vocab": [{"ko": "공룡", "en": "dinosaur"}, {"ko": "수영", "en": "swimming"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Adjective form used before a noun. 크다 → 큰 (big). 큰 공룡들 = big dinosaurs.", "example_in_sentence": "큰 공룡들"}, {"type": "grammar", "label": "~도", "exp": "Particle meaning ''even'' or ''also''. 공룡들도 = even dinosaurs.", "example_in_sentence": "공룡들도"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Auxiliary expressing possibility/ability. 할 (do) + ㄹ수 있다 → 할 수 있었다 (was able to).", "example_in_sentence": "할 수 있었다"}, {"type": "grammar", "label": "~다는 거예요", "exp": "Used to explain or pass on news: ''the point is that…''. 할 수 있었다 → 할 수 있었다는 거예요 (it turns out they could).", "example_in_sentence": "할 수 있었다는 거예요"}]}, {"text": "이 발견은 돌에 남은 발톱 자국 때문에 가능했어요.", "translation": "This discovery was possible because of claw marks left on stone.", "vocab": [{"ko": "발견", "en": "discovery"}, {"ko": "돌", "en": "stone"}, {"ko": "발톱", "en": "claw"}, {"ko": "자국", "en": "mark"}], "analysis": [{"type": "grammar", "label": "~ㄴ/은 (past modifier)", "exp": "Descriptive past modifier. 남다 (remain/be left) → 남은 (left) modifies 발톱 자국.", "example_in_sentence": "남은 발톱 자국"}, {"type": "grammar", "label": "~때문에", "exp": "Causal connector meaning ''because of/due to''. Shows reason: 발톱 자국 때문에 (because of claw marks).", "example_in_sentence": "발톱 자국 때문에"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending: 가능하다 (be possible) → 가능했어요 (was possible).", "example_in_sentence": "가능했어요"}]}, {"text": "강 근처에서 발견된 이 자국들을 보고 과학자들이 알게 되었어요.", "translation": "Scientists learned this by looking at these marks found near a river.", "vocab": [{"ko": "강", "en": "river"}, {"ko": "근처", "en": "nearby/vicinity"}, {"ko": "발견되다", "en": "to be discovered"}, {"ko": "알다", "en": "to know"}], "analysis": [{"type": "grammar", "label": "~ㄴ/은 (past modifier)", "exp": "Passive past modifier. 발견되다 (be discovered) → 발견된 (discovered) modifies 자국들.", "example_in_sentence": "발견된 이 자국들"}, {"type": "grammar", "label": "~고 (connective)", "exp": "Sequential/coordinate connector. Chains actions: 보다 (see) + 고 → 보고, then 알게 되었어요 (came to know).", "example_in_sentence": "보고"}, {"type": "grammar", "label": "~게 되다", "exp": "Auxiliary expressing resultative change of state. 알다 → 알게 되다 (came to know/ended up knowing).", "example_in_sentence": "알게 되었어요"}]}, {"text": "공룡들이 물속에서 발톱으로 헤엄쳤다는 증거예요.", "translation": "It is evidence that dinosaurs swam with their claws in the water.", "vocab": [{"ko": "물속", "en": "in water"}, {"ko": "발톱", "en": "claw"}, {"ko": "헤엄치다", "en": "to swim"}, {"ko": "증거", "en": "evidence"}], "analysis": [{"type": "grammar", "label": "~았/었다는", "exp": "Past statement + 는, used before a noun: ''that (they) did''. 헤엄치다 → 헤엄쳤다는 증거 = evidence that they swam.", "example_in_sentence": "헤엄쳤다는 증거"}, {"type": "grammar", "label": "이다/예요 (copula)", "exp": "Copular verb ''to be''. 증거 + 예요 (evidence + it is).", "example_in_sentence": "증거예요"}]}, {"text": "물론 공룡들의 수영 실력에는 한계가 있었어요.", "translation": "Of course, dinosaurs'' swimming ability had limitations.", "vocab": [{"ko": "물론", "en": "of course"}, {"ko": "수영", "en": "swimming"}, {"ko": "실력", "en": "ability/skill"}, {"ko": "한계", "en": "limitation"}], "analysis": [{"type": "grammar", "label": "~의 (possessive particle)", "exp": "Marks possessive/attributive relationship. 공룡들의 수영 실력 (dinosaurs'' swimming ability).", "example_in_sentence": "공룡들의"}, {"type": "grammar", "label": "~에는", "exp": "Topic particle on location/target. Marks specific scope: 실력에는 (as for ability).", "example_in_sentence": "실력에는"}, {"type": "expression", "label": "한계가 있다", "exp": "Collocation meaning ''to have limitations/limits''. Shows scope restriction of an ability.", "example_in_sentence": "한계가 있었어요"}]}, {"text": "깊은 곳까지 들어가기는 어려웠을 거예요.", "translation": "It would have been difficult to go into deep places.", "vocab": [{"ko": "깊다", "en": "to be deep"}, {"ko": "곳", "en": "place"}, {"ko": "들어가다", "en": "to go in/enter"}, {"ko": "어렵다", "en": "to be difficult"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Adjective form used before a noun. 깊다 → 깊은 (deep). 깊은 곳 = deep places.", "example_in_sentence": "깊은 곳"}, {"type": "grammar", "label": "~기", "exp": "Nominalizer converting verb to noun. 들어가다 → 들어가기 (entering/to enter).", "example_in_sentence": "들어가기"}, {"type": "grammar", "label": "~는", "exp": "Topic particle marking contrast/scope. 들어가기는 (as for entering).", "example_in_sentence": "들어가기는"}, {"type": "grammar", "label": "~았/었을 거예요", "exp": "A guess about the past: ''probably was'' or ''would have been''. 어렵다 → 어려웠을 거예요.", "example_in_sentence": "어려웠을 거예요"}]}, {"text": "하지만 얕은 물에서는 헤엄칠 수 있었다고 해요.", "translation": "But they say dinosaurs were able to swim in shallow water.", "vocab": [{"ko": "하지만", "en": "but/however"}, {"ko": "얕다", "en": "shallow"}, {"ko": "물", "en": "water"}, {"ko": "헤엄치다", "en": "to swim"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Adjective form used before a noun. 얕다 → 얕은 (shallow). 얕은 물 = shallow water.", "example_in_sentence": "얕은 물"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Auxiliary expressing ability/possibility in past: ~ㄹ 수 있었다 (was able to).", "example_in_sentence": "헤엄칠 수 있었다"}, {"type": "grammar", "label": "~다고 하다", "exp": "Indirect speech/reported statement. ~다 + 고 하다 (they say that).", "example_in_sentence": "헤엄칠 수 있었다고 해요"}]}, {"text": "이런 발견은 우리가 공룡에 대해 새롭게 생각하게 해줘요.", "translation": "This kind of discovery makes us think about dinosaurs in a new way.", "vocab": [{"ko": "발견", "en": "discovery"}, {"ko": "공룡", "en": "dinosaur"}, {"ko": "새롭다", "en": "to be new"}, {"ko": "생각하다", "en": "to think"}], "analysis": [{"type": "grammar", "label": "~게 하다", "exp": "Causative auxiliary expressing ''make/let someone do''. 생각하다 → 생각하게 하다 (make think).", "example_in_sentence": "생각하게 해줘요"}, {"type": "grammar", "label": "~에 대해", "exp": "Postposition marking target of action/thought. 공룡에 대해 (about dinosaurs).", "example_in_sentence": "공룡에 대해"}, {"type": "grammar", "label": "~게", "exp": "Adverbial marker modifying adjectives/adverbs. 새롭다 → 새롭게 (newly/in a new way).", "example_in_sentence": "새롭게"}]}, {"text": "공룡들이 생각보다 다양한 환경에서 살았다는 걸 보여줘요.", "translation": "It shows that dinosaurs lived in more diverse environments than we thought.", "vocab": [{"ko": "생각", "en": "thought/expectation"}, {"ko": "다양하다", "en": "diverse/varied"}, {"ko": "환경", "en": "environment"}, {"ko": "살다", "en": "to live"}], "analysis": [{"type": "grammar", "label": "~보다", "exp": "Comparative particle meaning ''more than/compared to''. 생각보다 (more than we thought).", "example_in_sentence": "생각보다"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "Descriptive modifier: 다양하다 → 다양한 (diverse) modifies 환경.", "example_in_sentence": "다양한 환경"}, {"type": "grammar", "label": "~았/었다는 걸", "exp": "Nominalizer with colloquial 걸 (= 것을). 살았다는 걸 (that [they] lived).", "example_in_sentence": "살았다는 걸"}, {"type": "grammar", "label": "~아/어주다", "exp": "Auxiliary showing benefit/favor. 보여주다 (show/demonstrate for someone).", "example_in_sentence": "보여줘요"}]}], "version": "s6"}', vocab = '[{"ko": "최근", "en": "recently", "note": ""}, {"ko": "과학자", "en": "scientist", "note": ""}, {"ko": "놀랍다", "en": "to be surprising; amazing", "note": ""}, {"ko": "사실", "en": "fact", "note": ""}, {"ko": "공룡", "en": "dinosaur", "note": ""}, {"ko": "수영", "en": "swimming", "note": ""}, {"ko": "발견", "en": "discovery", "note": ""}, {"ko": "돌", "en": "stone", "note": ""}, {"ko": "발톱", "en": "claw", "note": ""}, {"ko": "자국", "en": "mark", "note": ""}, {"ko": "강", "en": "river", "note": ""}, {"ko": "근처", "en": "nearby/vicinity", "note": ""}, {"ko": "발견되다", "en": "to be discovered", "note": ""}, {"ko": "알다", "en": "to know", "note": ""}, {"ko": "물속", "en": "in water", "note": ""}, {"ko": "헤엄치다", "en": "to swim", "note": ""}, {"ko": "증거", "en": "evidence", "note": ""}, {"ko": "물론", "en": "of course", "note": ""}, {"ko": "실력", "en": "ability/skill", "note": ""}, {"ko": "한계", "en": "limitation", "note": ""}, {"ko": "깊다", "en": "to be deep", "note": ""}, {"ko": "곳", "en": "place", "note": ""}, {"ko": "들어가다", "en": "to go in/enter", "note": ""}, {"ko": "어렵다", "en": "to be difficult", "note": ""}, {"ko": "하지만", "en": "but/however", "note": ""}, {"ko": "얕다", "en": "shallow", "note": ""}, {"ko": "물", "en": "water", "note": ""}, {"ko": "새롭다", "en": "to be new", "note": ""}, {"ko": "생각하다", "en": "to think", "note": ""}, {"ko": "생각", "en": "thought/expectation", "note": ""}, {"ko": "다양하다", "en": "diverse/varied", "note": ""}, {"ko": "환경", "en": "environment", "note": ""}, {"ko": "살다", "en": "to live", "note": ""}]', grammar = '{"patterns": [{"name": "~았/었어요", "level": "Beginner", "exp": "Past tense ending for statements. Marks completion of action: 발견하다 (discover) → 발견했어요 (discovered).", "ex_ko": "최근 과학자들이 놀라운 사실을 발견했어요.", "ex_en": "Recently, scientists discovered a surprising fact."}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Beginner", "exp": "Adjective form used before a noun. 얕다 → 얕은 (shallow). 얕은 물 = shallow water.", "ex_ko": "티라노사우루스(T-Rex) 같은 큰 공룡들도 수영을 할 수 있었다는 거예요.", "ex_en": "It means that even large dinosaurs like Tyrannosaurus (T-Rex) were able to swim."}, {"name": "~도", "level": "Beginner", "exp": "Particle meaning ''even'' or ''also''. 공룡들도 = even dinosaurs.", "ex_ko": "티라노사우루스(T-Rex) 같은 큰 공룡들도 수영을 할 수 있었다는 거예요.", "ex_en": "It means that even large dinosaurs like Tyrannosaurus (T-Rex) were able to swim."}, {"name": "~ㄹ 수 있다", "level": "Beginner", "exp": "Auxiliary expressing possibility/ability. 할 (do) + ㄹ수 있다 → 할 수 있었다 (was able to).", "ex_ko": "티라노사우루스(T-Rex) 같은 큰 공룡들도 수영을 할 수 있었다는 거예요.", "ex_en": "It means that even large dinosaurs like Tyrannosaurus (T-Rex) were able to swim."}, {"name": "~다는 거예요", "level": "Beginner", "exp": "Used to explain or pass on news: ''the point is that…''. 할 수 있었다 → 할 수 있었다는 거예요 (it turns out they could).", "ex_ko": "티라노사우루스(T-Rex) 같은 큰 공룡들도 수영을 할 수 있었다는 거예요.", "ex_en": "It means that even large dinosaurs like Tyrannosaurus (T-Rex) were able to swim."}, {"name": "~ㄴ/은 (past modifier)", "level": "Beginner", "exp": "Passive past modifier. 발견되다 (be discovered) → 발견된 (discovered) modifies 자국들.", "ex_ko": "이 발견은 돌에 남은 발톱 자국 때문에 가능했어요.", "ex_en": "This discovery was possible because of claw marks left on stone."}, {"name": "~때문에", "level": "Beginner", "exp": "Causal connector meaning ''because of/due to''. Shows reason: 발톱 자국 때문에 (because of claw marks).", "ex_ko": "이 발견은 돌에 남은 발톱 자국 때문에 가능했어요.", "ex_en": "This discovery was possible because of claw marks left on stone."}, {"name": "~고 (connective)", "level": "Beginner", "exp": "Sequential/coordinate connector. Chains actions: 보다 (see) + 고 → 보고, then 알게 되었어요 (came to know).", "ex_ko": "강 근처에서 발견된 이 자국들을 보고 과학자들이 알게 되었어요.", "ex_en": "Scientists learned this by looking at these marks found near a river."}, {"name": "~게 되다", "level": "Beginner", "exp": "Auxiliary expressing resultative change of state. 알다 → 알게 되다 (came to know/ended up knowing).", "ex_ko": "강 근처에서 발견된 이 자국들을 보고 과학자들이 알게 되었어요.", "ex_en": "Scientists learned this by looking at these marks found near a river."}, {"name": "~았/었다는", "level": "Beginner", "exp": "Past statement + 는, used before a noun: ''that (they) did''. 헤엄치다 → 헤엄쳤다는 증거 = evidence that they swam.", "ex_ko": "공룡들이 물속에서 발톱으로 헤엄쳤다는 증거예요.", "ex_en": "It is evidence that dinosaurs swam with their claws in the water."}, {"name": "이다/예요 (copula)", "level": "Beginner", "exp": "Copular verb ''to be''. 증거 + 예요 (evidence + it is).", "ex_ko": "공룡들이 물속에서 발톱으로 헤엄쳤다는 증거예요.", "ex_en": "It is evidence that dinosaurs swam with their claws in the water."}, {"name": "~의 (possessive particle)", "level": "Beginner", "exp": "Marks possessive/attributive relationship. 공룡들의 수영 실력 (dinosaurs'' swimming ability).", "ex_ko": "물론 공룡들의 수영 실력에는 한계가 있었어요.", "ex_en": "Of course, dinosaurs'' swimming ability had limitations."}, {"name": "~에는", "level": "Beginner", "exp": "Topic particle on location/target. Marks specific scope: 실력에는 (as for ability).", "ex_ko": "물론 공룡들의 수영 실력에는 한계가 있었어요.", "ex_en": "Of course, dinosaurs'' swimming ability had limitations."}, {"name": "~기", "level": "Beginner", "exp": "Nominalizer converting verb to noun. 들어가다 → 들어가기 (entering/to enter).", "ex_ko": "깊은 곳까지 들어가기는 어려웠을 거예요.", "ex_en": "It would have been difficult to go into deep places."}, {"name": "~는", "level": "Beginner", "exp": "Topic particle marking contrast/scope. 들어가기는 (as for entering).", "ex_ko": "깊은 곳까지 들어가기는 어려웠을 거예요.", "ex_en": "It would have been difficult to go into deep places."}]}', updated_at = now() where article_id = 'movadwfemwyy' and md5(translation) = '881d1c993fa8e8aa6d1de9d32e7ae241';
update public.article_cache set translation = '{"sentences": [{"text": "미국의 유명한 범죄자였던 제프리 엡스타인의 마지막 메모가 공개되었어요.", "idx": 0, "translation": "The last memo of Jeffrey Epstein, a famous American criminal, was made public.", "vocab": [{"ko": "범죄자", "en": "criminal", "note": "범죄 (crime) + 자 (person)"}, {"ko": "공개되다", "en": "to be made public, disclosed"}, {"ko": "메모", "en": "memo, note"}], "grammar": [{"pattern": "~ㄴ/은 N", "exp": "modifies a noun with past tense meaning", "example_in_sentence": "유명한 범죄자였던 제프리 엡스타인"}, {"pattern": "~어/아지다", "exp": "passive voice or state change", "example_in_sentence": "공개되었어요"}], "analysis": []}, {"text": "엡스타인은 2019년 감옥에서 세상을 떠났다고 알려진 인물입니다", "idx": 1, "translation": "Epstein is a person known to have passed away in prison in 2019.", "vocab": [{"ko": "감옥", "en": "prison, jail"}, {"ko": "세상을 떠나다", "en": "to pass away, die", "note": "literal: leave the world"}], "grammar": [{"pattern": "~ㄴ다고 알려지다", "exp": "reported/known to do something", "example_in_sentence": "세상을 떠났다고 알려진"}], "analysis": []}, {"text": "이번에 공개된 메모는 그가 죽기 전에 작성한 것으로 알려졌어요.", "idx": 2, "translation": "The memo released this time is known to have been written before he died.", "vocab": [{"ko": "공개되다", "en": "to be disclosed, made public"}, {"ko": "작성하다", "en": "to write, compose"}], "grammar": [{"pattern": "~ㄴ 것으로 알려지다", "exp": "it is known/reported that", "example_in_sentence": "작성한 것으로 알려졌어요"}], "analysis": []}, {"text": "메모에는 개인적인 생각들이 적혀 있었습니다.", "idx": 3, "translation": "The memo contained personal thoughts.", "vocab": [{"ko": "개인적", "en": "personal, individual"}, {"ko": "생각", "en": "thought, idea"}], "grammar": [], "analysis": []}, {"text": "이 사건은 미국 사회에서 큰 관심을 받고 있어요.", "idx": 4, "translation": "This case is receiving great interest in American society.", "vocab": [{"ko": "사건", "en": "case, incident, event"}, {"ko": "관심", "en": "interest, attention"}], "grammar": [{"pattern": "~고 있다", "exp": "progressive or ongoing state", "example_in_sentence": "받고 있어요"}], "analysis": []}, {"text": "많은 사람들이 이 메모의 내용에 대해 궁금해하고 있습니다.", "idx": 5, "translation": "Many people are curious about the contents of this memo.", "vocab": [{"ko": "내용", "en": "content, substance"}, {"ko": "궁금해하다", "en": "to be curious, wonder about"}], "grammar": [{"pattern": "~고 있다", "exp": "progressive state or continuous action", "example_in_sentence": "궁금해하고 있습니다"}], "analysis": []}, {"text": "전문가들은 이 메모가 당시 상황을 이해하는 데 도움이 될 것이라고 말했어요.", "idx": 6, "translation": "Experts said this memo would be helpful in understanding the situation at that time.", "vocab": [{"ko": "전문가", "en": "expert, specialist"}, {"ko": "도움이 되다", "en": "to be helpful, useful"}], "grammar": [{"pattern": "~는 데 도움이 되다", "exp": "to be helpful in/for [doing something]", "example_in_sentence": "이해하는 데 도움이 될 것"}], "analysis": []}, {"text": "하지만 아직 확인되지 않은 내용들도 많다고 합니다.", "idx": 7, "translation": "However, it is said that there is still a lot of information that has not been confirmed.", "vocab": [{"ko": "확인되다", "en": "to be confirmed, verified"}, {"ko": "내용", "en": "content, matter"}], "grammar": [{"pattern": "~지 않은", "exp": "negative past modifier form", "example_in_sentence": "확인되지 않은 내용"}, {"pattern": "~다고 하다", "exp": "reported/said to be", "example_in_sentence": "많다고 합니다"}], "analysis": []}]}', vocab = '[{"ko": "범죄자", "en": "criminal", "note": "범죄 (crime) + 자 (person)"}, {"ko": "공개되다", "en": "to be made public, disclosed", "note": ""}, {"ko": "메모", "en": "memo, note", "note": ""}, {"ko": "감옥", "en": "prison, jail", "note": ""}, {"ko": "세상을 떠나다", "en": "to pass away, die", "note": "literal: leave the world"}, {"ko": "작성하다", "en": "to write, compose", "note": ""}, {"ko": "개인적", "en": "personal, individual", "note": ""}, {"ko": "생각", "en": "thought, idea", "note": ""}, {"ko": "사건", "en": "case, incident, event", "note": ""}, {"ko": "관심", "en": "interest, attention", "note": ""}, {"ko": "내용", "en": "content, substance", "note": ""}, {"ko": "궁금해하다", "en": "to be curious, wonder about", "note": ""}, {"ko": "전문가", "en": "expert, specialist", "note": ""}, {"ko": "도움이 되다", "en": "to be helpful, useful", "note": ""}, {"ko": "확인되다", "en": "to be confirmed, verified", "note": ""}, {"word": "관심을 받다", "reading": "gwansimeul batda", "meaning": "to receive attention; to attract interest", "context": "이 사건은 미국 사회에서 큰 관심을 받고"}, {"word": "상황", "reading": "sanghwang", "meaning": "situation; circumstance; state of affairs", "context": "당시 상황을 이해하는 데 도움이"}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'movf6fzcx85y' and md5(translation) = '4601f963e8784c846abf782e95a46893';
update public.article_cache set translation = '{"texts": ["Something strange happened at a large supermarket in the United States. A person poured both milk and cereal all over their own body. Someone who witnessed this scene posted about it on the internet. Many people were shocked when they saw this story. We don''t know why this person did such a thing. It seems the supermarket employees must have been confused too. On the internet, these kinds of unusual stories often become topics of discussion. People enjoy sharing amusing or strange events.", "Korea''s teacher shortage becomes serious, school classes disrupted", "What is an \"anxiety bag\"? A popular trend", "The United States and China resume talks over trade issues", "\"Talking pig\" becomes an SNS star", "Apple greatly improves iPhone speed with new AI chip"], "sentences": [{"text": "미국의 한 대형마트에서 이상한 일이 일어났어요.", "translation": "A strange incident happened at a large supermarket in the United States.", "vocab": [{"ko": "대형마트", "en": "large supermarket"}, {"ko": "이상하다", "en": "to be strange; odd"}, {"ko": "일어나다", "en": "to happen, to occur"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending for polite/casual formal speech. Marks completed action: 일어나다 → 일어났어요.", "example_in_sentence": "일어났어요"}, {"type": "grammar", "label": "의 (genitive particle)", "exp": "Marks possession or association: 미국 (United States) + 의 = ''of the United States''.", "example_in_sentence": "미국의"}]}, {"text": "어떤 사람이 우유와 시리얼을 자신의 몸에 모두 부었어요.", "translation": "A certain person poured milk and cereal all over their own body.", "vocab": [{"ko": "우유", "en": "milk"}, {"ko": "시리얼", "en": "cereal"}, {"ko": "붓다", "en": "to pour"}, {"ko": "모두", "en": "all, completely"}], "analysis": [{"type": "grammar", "label": "~과/와 (conjunction particle)", "exp": "Joins two nouns: 우유 + 와 + 시리얼 = ''milk and cereal''.", "example_in_sentence": "우유와 시리얼을"}, {"type": "grammar", "label": "~을/를 (accusative particle)", "exp": "Marks direct object: 우유와 시리얼 + 을 = ''milk and cereal (object of pouring)''.", "example_in_sentence": "시리얼을"}, {"type": "grammar", "label": "~에 (locative particle)", "exp": "Marks location/destination where action occurs: 몸 + 에 = ''on/to the body''.", "example_in_sentence": "몸에"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 붓다 is ㅅ-irregular: the ㅅ drops before a vowel, so 붓다 → 부었어요 (poured).", "example_in_sentence": "부었어요"}]}, {"text": "이 장면을 본 사람이 인터넷에 글을 올렸어요.", "translation": "A person who saw this scene posted a message on the internet.", "vocab": [{"ko": "장면", "en": "scene"}, {"ko": "인터넷", "en": "internet"}, {"ko": "글", "en": "post, writing, message"}, {"ko": "올리다", "en": "to post, to upload"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past form of a verb used before a noun. 보다 → 본 사람 = the person who saw.", "example_in_sentence": "본 사람이"}, {"type": "grammar", "label": "~을/를 (accusative particle)", "exp": "Marks direct object: 장면 + 을 = ''scene (object of seeing)''.", "example_in_sentence": "장면을"}, {"type": "grammar", "label": "~에 (locative particle)", "exp": "Marks location where action happens: 인터넷 + 에 = ''on the internet''.", "example_in_sentence": "인터넷에"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense: 올리다 → 올렸어요 (posted).", "example_in_sentence": "올렸어요"}]}, {"text": "많은 사람들이 이 이야기를 보고 놀랐어요.", "translation": "Many people saw this story and were surprised.", "vocab": [{"ko": "많다", "en": "to be many; much"}, {"ko": "사람들", "en": "people (plural)"}, {"ko": "이야기", "en": "story, talk"}, {"ko": "놀라다", "en": "to be surprised, to be amazed"}], "analysis": [{"type": "grammar", "label": "~이/가 (subject particle)", "exp": "Marks the subject. 사람들 + 이 = many people (did it).", "example_in_sentence": "사람들이"}, {"type": "grammar", "label": "~을/를 (accusative particle)", "exp": "Marks direct object: 이야기 + 를 = ''story (object of seeing)''.", "example_in_sentence": "이야기를"}, {"type": "grammar", "label": "~고 (conjunctive ending)", "exp": "Joins two actions sequentially: 보다 → 보고 (saw) + 놀라다 (were surprised).", "example_in_sentence": "보고"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense: 놀라다 → 놀랐어요 (were surprised).", "example_in_sentence": "놀랐어요"}]}, {"text": "왜 이런 일을 했는지는 알 수 없어요.", "translation": "It is not possible to know why this person did such a thing.", "vocab": [{"ko": "왜", "en": "why"}, {"ko": "이런", "en": "such, like this"}, {"ko": "하다", "en": "to do"}, {"ko": "알다", "en": "to know"}], "analysis": [{"type": "grammar", "label": "~았/었는지", "exp": "Turns a question into part of a sentence: ''why … did''. 하다 → 했는지 (why they did it). 는 adds emphasis.", "example_in_sentence": "했는지는"}, {"type": "grammar", "label": "~을/를 (accusative particle)", "exp": "Marks direct object: 일 + 을 = ''thing (object of doing)''.", "example_in_sentence": "일을"}, {"type": "grammar", "label": "~(으)ㄹ 수 없다", "exp": "Means ''cannot''. 알다 → 알 수 없어요 (can''t know).", "example_in_sentence": "알 수 없어요"}]}, {"text": "마트 직원들도 당황했을 것 같아요.", "translation": "The supermarket employees probably would have been confused too.", "vocab": [{"ko": "마트", "en": "supermarket (mart)"}, {"ko": "직원", "en": "employee, staff"}, {"ko": "당황하다", "en": "to be confused, to be bewildered"}], "analysis": [{"type": "grammar", "label": "~도 (inclusive particle)", "exp": "Also, too: 직원들 + 도 = ''employees also''.", "example_in_sentence": "직원들도"}, {"type": "grammar", "label": "~았/었을 것 같다", "exp": "A guess about the past: ''must have'' or ''probably''. 당황하다 → 당황했을 것 같아요 (they were probably flustered).", "example_in_sentence": "당황했을 것 같아요"}]}, {"text": "인터넷에서는 이런 특이한 이야기들이 자주 화제가 되어요.", "translation": "On the internet, such unusual stories often become topics of discussion.", "vocab": [{"ko": "특이하다", "en": "unusual, extraordinary, distinctive"}, {"ko": "화제", "en": "topic, subject (of discussion)"}, {"ko": "자주", "en": "often, frequently"}], "analysis": [{"type": "grammar", "label": "~에서는 (locative + contrast particle)", "exp": "Location + contrast: 인터넷 + 에서 + 는 = ''on the internet (as for, in particular)''.", "example_in_sentence": "인터넷에서는"}, {"type": "grammar", "label": "~이 (nominative particle)", "exp": "Marks subject: 이야기들 + 이 = ''stories (subject)''.", "example_in_sentence": "이야기들이"}, {"type": "expression", "label": "화제가 되다 (become a topic)", "exp": "Idiom: 화제 (topic) + 되다 (become) = ''become a topic of discussion/popular subject''.", "example_in_sentence": "화제가 되어요"}]}, {"text": "사람들은 재미있거나 이상한 일들을 나누는 것을 좋아해요.", "translation": "People like to share things that are fun or strange.", "vocab": [{"ko": "재미있다", "en": "to be fun; interesting"}, {"ko": "나누다", "en": "to share, to divide"}, {"ko": "좋아하다", "en": "to like, to enjoy"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic particle)", "exp": "Marks subject/topic: 사람들 + 은 = ''people (subject/topic)''.", "example_in_sentence": "사람들은"}, {"type": "grammar", "label": "~거나", "exp": "Means ''or'' between verbs or adjectives. 재미있다 → 재미있거나 (fun or …).", "example_in_sentence": "재미있거나"}, {"type": "grammar", "label": "~는 것을 (gerund + accusative)", "exp": "Nominalization: 나누다 → 나누는 것 = ''the act of sharing'' (object).", "example_in_sentence": "나누는 것을"}, {"type": "grammar", "label": "~어/아요 (present polite ending)", "exp": "Present tense: 좋아하다 → 좋아해요.", "example_in_sentence": "좋아해요"}]}], "version": "s6"}', vocab = '[{"ko": "대형마트", "en": "large supermarket", "note": ""}, {"ko": "이상하다", "en": "to be strange; odd", "note": ""}, {"ko": "일어나다", "en": "to happen, to occur", "note": ""}, {"ko": "우유", "en": "milk", "note": ""}, {"ko": "시리얼", "en": "cereal", "note": ""}, {"ko": "붓다", "en": "to pour", "note": ""}, {"ko": "모두", "en": "all, completely", "note": ""}, {"ko": "장면", "en": "scene", "note": ""}, {"ko": "인터넷", "en": "internet", "note": ""}, {"ko": "글", "en": "post, writing, message", "note": ""}, {"ko": "올리다", "en": "to post, to upload", "note": ""}, {"ko": "많다", "en": "to be many; much", "note": ""}, {"ko": "사람들", "en": "people (plural)", "note": ""}, {"ko": "이야기", "en": "story, talk", "note": ""}, {"ko": "놀라다", "en": "to be surprised, to be amazed", "note": ""}, {"ko": "왜", "en": "why", "note": ""}, {"ko": "이런", "en": "such, like this", "note": ""}, {"ko": "하다", "en": "to do", "note": ""}, {"ko": "알다", "en": "to know", "note": ""}, {"ko": "마트", "en": "supermarket (mart)", "note": ""}, {"ko": "직원", "en": "employee, staff", "note": ""}, {"ko": "당황하다", "en": "to be confused, to be bewildered", "note": ""}, {"ko": "특이하다", "en": "unusual, extraordinary, distinctive", "note": ""}, {"ko": "화제", "en": "topic, subject (of discussion)", "note": ""}, {"ko": "자주", "en": "often, frequently", "note": ""}, {"ko": "재미있다", "en": "to be fun; interesting", "note": ""}, {"ko": "나누다", "en": "to share, to divide", "note": ""}, {"ko": "좋아하다", "en": "to like, to enjoy", "note": ""}, {"ko": "자신의", "en": "one''s own", "note": "possessive form of 자신 (oneself)"}, {"ko": "알 수 없다", "en": "to be unclear, impossible to know", "note": "literally ''cannot know''; used for unknowable facts"}]', grammar = '{"patterns": [{"name": "~았/었어요", "level": "Beginner", "exp": "Past tense ending for polite/casual formal speech. Marks completed action: 일어나다 → 일어났어요.", "ex_ko": "미국의 한 대형마트에서 이상한 일이 일어났어요.", "ex_en": "A strange incident happened at a large supermarket in the United States."}, {"name": "의 (genitive particle)", "level": "Beginner", "exp": "Marks possession or association: 미국 (United States) + 의 = ''of the United States''.", "ex_ko": "미국의 한 대형마트에서 이상한 일이 일어났어요.", "ex_en": "A strange incident happened at a large supermarket in the United States."}, {"name": "~과/와 (conjunction particle)", "level": "Beginner", "exp": "Joins two nouns: 우유 + 와 + 시리얼 = ''milk and cereal''.", "ex_ko": "어떤 사람이 우유와 시리얼을 자신의 몸에 모두 부었어요.", "ex_en": "A certain person poured milk and cereal all over their own body."}, {"name": "~을/를 (accusative particle)", "level": "Beginner", "exp": "Marks direct object: 우유와 시리얼 + 을 = ''milk and cereal (object of pouring)''.", "ex_ko": "어떤 사람이 우유와 시리얼을 자신의 몸에 모두 부었어요.", "ex_en": "A certain person poured milk and cereal all over their own body."}, {"name": "~에 (locative particle)", "level": "Beginner", "exp": "Marks location/destination where action occurs: 몸 + 에 = ''on/to the body''.", "ex_ko": "어떤 사람이 우유와 시리얼을 자신의 몸에 모두 부었어요.", "ex_en": "A certain person poured milk and cereal all over their own body."}, {"name": "~(으)ㄴ (past modifier)", "level": "Beginner", "exp": "Past form of a verb used before a noun. 보다 → 본 사람 = the person who saw.", "ex_ko": "이 장면을 본 사람이 인터넷에 글을 올렸어요.", "ex_en": "A person who saw this scene posted a message on the internet."}, {"name": "~이/가 (subject particle)", "level": "Beginner", "exp": "Marks the subject. 사람들 + 이 = many people (did it).", "ex_ko": "많은 사람들이 이 이야기를 보고 놀랐어요.", "ex_en": "Many people saw this story and were surprised."}, {"name": "~고 (conjunctive ending)", "level": "Beginner", "exp": "Joins two actions sequentially: 보다 → 보고 (saw) + 놀라다 (were surprised).", "ex_ko": "많은 사람들이 이 이야기를 보고 놀랐어요.", "ex_en": "Many people saw this story and were surprised."}, {"name": "~았/었는지", "level": "Beginner", "exp": "Turns a question into part of a sentence: ''why … did''. 하다 → 했는지 (why they did it). 는 adds emphasis.", "ex_ko": "왜 이런 일을 했는지는 알 수 없어요.", "ex_en": "It is not possible to know why this person did such a thing."}, {"name": "~(으)ㄹ 수 없다", "level": "Beginner", "exp": "Means ''cannot''. 알다 → 알 수 없어요 (can''t know).", "ex_ko": "왜 이런 일을 했는지는 알 수 없어요.", "ex_en": "It is not possible to know why this person did such a thing."}, {"name": "~도 (inclusive particle)", "level": "Beginner", "exp": "Also, too: 직원들 + 도 = ''employees also''.", "ex_ko": "마트 직원들도 당황했을 것 같아요.", "ex_en": "The supermarket employees probably would have been confused too."}, {"name": "~았/었을 것 같다", "level": "Beginner", "exp": "A guess about the past: ''must have'' or ''probably''. 당황하다 → 당황했을 것 같아요 (they were probably flustered).", "ex_ko": "마트 직원들도 당황했을 것 같아요.", "ex_en": "The supermarket employees probably would have been confused too."}, {"name": "~에서는 (locative + contrast particle)", "level": "Beginner", "exp": "Location + contrast: 인터넷 + 에서 + 는 = ''on the internet (as for, in particular)''.", "ex_ko": "인터넷에서는 이런 특이한 이야기들이 자주 화제가 되어요.", "ex_en": "On the internet, such unusual stories often become topics of discussion."}, {"name": "~이 (nominative particle)", "level": "Beginner", "exp": "Marks subject: 이야기들 + 이 = ''stories (subject)''.", "ex_ko": "인터넷에서는 이런 특이한 이야기들이 자주 화제가 되어요.", "ex_en": "On the internet, such unusual stories often become topics of discussion."}, {"name": "~은/는 (topic particle)", "level": "Beginner", "exp": "Marks subject/topic: 사람들 + 은 = ''people (subject/topic)''.", "ex_ko": "사람들은 재미있거나 이상한 일들을 나누는 것을 좋아해요.", "ex_en": "People like to share things that are fun or strange."}]}', updated_at = now() where article_id = 'movfk0pvgzjt' and md5(translation) = '2c82e20c064658cb50b2c776eef90484';
update public.article_cache set translation = '{"texts": ["An American man posted a special photo on the internet. It showed how you could tell how many times his girlfriend had undergone cancer treatment (a medical method to treat cancer) by looking at her hair.", "When you receive cancer treatment, your hair falls out. When the treatment ends, your hair grows back. As this process repeats, special patterns form in the hair.", "Like tree rings, the number of treatments was recorded in her hair. Many people were amazed when they saw this photo. They said it was a remarkable record created by nature.", "This photo gave hope to cancer patients and their families. It conveyed the message that even a difficult treatment process can leave behind a beautiful trace."], "sentences": [{"text": "미국의 한 남성이 특별한 사진을 인터넷에 올렸어요.", "translation": "A man from the US posted a special photo on the internet.", "vocab": [{"ko": "미국", "en": "US, America"}, {"ko": "남성", "en": "man, male"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "인터넷", "en": "internet"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending expressing completed action. 올리다 (to post) → 올렸어요.", "example_in_sentence": "올렸어요"}, {"type": "grammar", "label": "의 (possessive particle)", "exp": "Marks possession or attribution. Connects noun to noun: 미국 (US) + 의 → 미국의 (of/from the US).", "example_in_sentence": "미국의"}]}, {"text": "그의 여자친구가 항암 치료(암을 치료하는 의학적 방법)를 받은 횟수를 머리카락으로 알 수 있다는 내용이었어요.", "translation": "The content was that you could tell the number of times his girlfriend underwent cancer treatment by her hair.", "vocab": [{"ko": "여자친구", "en": "girlfriend"}, {"ko": "항암 치료", "en": "cancer treatment, chemotherapy"}, {"ko": "머리카락", "en": "hair"}, {"ko": "알다", "en": "to know, to tell"}], "analysis": [{"type": "grammar", "label": "~다는 내용이다", "exp": "Says what something was about: ''it was (about the fact) that…''. 알 수 있다 → 알 수 있다는 내용이었어요.", "example_in_sentence": "알 수 있다는 내용이었어요"}, {"type": "grammar", "label": "~을/를 받다", "exp": "받다 here means ''to receive'' or ''to undergo''. 치료를 받다 = to get treatment.", "example_in_sentence": "치료(암을 치료하는 의학적 방법)를 받은"}, {"type": "grammar", "label": "~은/ㄴ (past participle modifier)", "exp": "Modifies noun with past tense meaning. 받다 → 받은 (underwent). Modifies 횟수 (number of times).", "example_in_sentence": "받은 횟수"}, {"type": "grammar", "label": "~으로 (instrumental particle)", "exp": "Marks means or medium. 머리카락으로 (by/through hair).", "example_in_sentence": "머리카락으로"}]}, {"text": "항암 치료를 받으면 머리카락이 빠져요.", "translation": "When you undergo cancer treatment, your hair falls out.", "vocab": [{"ko": "항암 치료", "en": "cancer treatment"}, {"ko": "빠지다", "en": "to fall out, to drop"}], "analysis": [{"type": "grammar", "label": "~으면 (conditional)", "exp": "Conditional ending expressing ''if/when.'' 받다 → 받으면 (when receive/undergo).", "example_in_sentence": "받으면"}]}, {"text": "치료가 끝나면 머리카락이 다시 자라요.", "translation": "When treatment ends, hair grows back again.", "vocab": [{"ko": "치료", "en": "treatment"}, {"ko": "끝나다", "en": "to end, to finish"}, {"ko": "자라다", "en": "to grow"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "Means ''when'' or ''if''. 끝나다 → 끝나면 (when it ends).", "example_in_sentence": "끝나면"}]}, {"text": "이 과정이 반복되면서 머리카락에 특별한 무늬가 생겨요.", "translation": "As this process repeats, a special pattern forms in the hair.", "vocab": [{"ko": "과정", "en": "process"}, {"ko": "반복되다", "en": "to be repeated"}, {"ko": "무늬", "en": "pattern, design"}, {"ko": "생기다", "en": "to form, to appear"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "Means ''as'' or ''while'': two things happen together. 반복되다 → 반복되면서 (as it repeats).", "example_in_sentence": "반복되면서"}]}, {"text": "나무의 나이테처럼 머리카락에도 치료 횟수가 기록되었어요.", "translation": "Like the rings of a tree, the number of treatments was recorded in her hair too.", "vocab": [{"ko": "나무", "en": "tree"}, {"ko": "나이테", "en": "tree ring"}, {"ko": "기록되다", "en": "to be recorded"}], "analysis": [{"type": "expression", "label": "~처럼 (like, similar to)", "exp": "Comparative particle meaning ''like'' or ''similar to.'' 나이테처럼 (like tree rings).", "example_in_sentence": "나이테처럼"}, {"type": "grammar", "label": "~도 (inclusive particle)", "exp": "Adds ''also/too'' meaning. 머리카락에도 (in the hair as well).", "example_in_sentence": "머리카락에도"}, {"type": "grammar", "label": "~았/었어요 (passive)", "exp": "Past tense. 기록되다 (to be recorded, passive form) → 기록되었어요.", "example_in_sentence": "기록되었어요"}]}, {"text": "많은 사람들이 이 사진을 보고 놀라워했어요.", "translation": "Many people saw this photo and were amazed.", "vocab": [{"ko": "많다", "en": "to be many, much"}, {"ko": "사람", "en": "person"}, {"ko": "놀라워하다", "en": "to be amazed, to be surprised"}], "analysis": [{"type": "grammar", "label": "~고 (coordinating connective)", "exp": "Connects two actions in sequence. 보다 (to see) → 보고, then 놀라워하다 (to be amazed).", "example_in_sentence": "보고"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 놀라워하다 → 놀라워했어요.", "example_in_sentence": "놀라워했어요"}]}, {"text": "자연이 만든 신기한 기록이라고 말했어요.", "translation": "People said it was an amazing record made by nature.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "만들다", "en": "to make"}, {"ko": "신기하다", "en": "to be amazing; fascinating"}, {"ko": "기록", "en": "record"}], "analysis": [{"type": "grammar", "label": "~ㄴ/은 (past participle modifier)", "exp": "Modifies noun with past action. 만들다 → 만든 (made). Modifies 기록 (record).", "example_in_sentence": "만든"}, {"type": "grammar", "label": "~(이)라고 말하다", "exp": "Quotes what someone said about a noun. 기록 + 이라고 말했어요 = said it was a record.", "example_in_sentence": "기록이라고 말했어요"}]}, {"text": "이 사진은 암 환자와 가족들에게 희망을 주었어요.", "translation": "This photo gave hope to cancer patients and their families.", "vocab": [{"ko": "암 환자", "en": "cancer patient"}, {"ko": "가족", "en": "family"}, {"ko": "희망", "en": "hope"}, {"ko": "주다", "en": "to give"}], "analysis": [{"type": "grammar", "label": "~과/와 (connective particle)", "exp": "Connects two nouns meaning ''and.'' 환자와 가족 (patients and families).", "example_in_sentence": "환자와 가족"}, {"type": "grammar", "label": "~에게 (indirect object particle)", "exp": "Marks recipient or target. 가족들에게 (to families).", "example_in_sentence": "가족들에게"}, {"type": "expression", "label": "희망을 주다", "exp": "Verbal collocation meaning ''to give hope/to inspire hope.'' 주다 → 주었어요 (gave, past).", "example_in_sentence": "희망을 주었어요"}]}, {"text": "힘든 치료 과정도 아름다운 흔적으로 남을 수 있다는 메시지를 전했어요.", "translation": "They conveyed a message that even difficult treatment processes can remain as beautiful traces.", "vocab": [{"ko": "힘들다", "en": "to be difficult, hard"}, {"ko": "과정", "en": "process"}, {"ko": "아름답다", "en": "to be beautiful"}, {"ko": "흔적", "en": "trace, mark"}], "analysis": [{"type": "grammar", "label": "~도 (inclusive particle)", "exp": "Adds ''even/too'' meaning to emphasize. 과정도 (even the process).", "example_in_sentence": "과정도"}, {"type": "grammar", "label": "~으로 (transformative particle)", "exp": "Marks transformation or state change. 흔적으로 (as/into traces).", "example_in_sentence": "흔적으로"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can''. 남다 → 남을 수 있다 (can remain).", "example_in_sentence": "남을 수 있다"}, {"type": "grammar", "label": "~다는 + noun", "exp": "Links a statement to the noun after it: ''the message that…''. 있다 → 있다는 메시지.", "example_in_sentence": "있다는 메시지"}]}], "version": "s6"}', vocab = '[{"ko": "미국", "en": "US, America", "note": ""}, {"ko": "남성", "en": "man, male", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "인터넷", "en": "internet", "note": ""}, {"ko": "여자친구", "en": "girlfriend", "note": ""}, {"ko": "항암 치료", "en": "cancer treatment, chemotherapy", "note": ""}, {"ko": "머리카락", "en": "hair", "note": ""}, {"ko": "알다", "en": "to know, to tell", "note": ""}, {"ko": "빠지다", "en": "to fall out, to drop", "note": ""}, {"ko": "치료", "en": "treatment", "note": ""}, {"ko": "끝나다", "en": "to end, to finish", "note": ""}, {"ko": "자라다", "en": "to grow", "note": ""}, {"ko": "과정", "en": "process", "note": ""}, {"ko": "반복되다", "en": "to be repeated", "note": ""}, {"ko": "무늬", "en": "pattern, design", "note": ""}, {"ko": "생기다", "en": "to form, to appear", "note": ""}, {"ko": "나무", "en": "tree", "note": ""}, {"ko": "나이테", "en": "tree ring", "note": ""}, {"ko": "기록되다", "en": "to be recorded", "note": ""}, {"ko": "많다", "en": "to be many, much", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "놀라워하다", "en": "to be amazed, to be surprised", "note": ""}, {"ko": "자연", "en": "nature", "note": ""}, {"ko": "만들다", "en": "to make", "note": ""}, {"ko": "신기하다", "en": "to be amazing; fascinating", "note": ""}, {"ko": "기록", "en": "record", "note": ""}, {"ko": "암 환자", "en": "cancer patient", "note": ""}, {"ko": "가족", "en": "family", "note": ""}, {"ko": "희망", "en": "hope", "note": ""}, {"ko": "주다", "en": "to give", "note": ""}, {"ko": "힘들다", "en": "to be difficult, hard", "note": ""}, {"ko": "아름답다", "en": "to be beautiful", "note": ""}, {"ko": "흔적", "en": "trace, mark", "note": ""}, {"ko": "올리다", "en": "to post; to upload", "note": "common for social media and internet content"}, {"ko": "횟수", "en": "number of times; frequency", "note": "noun for counting occurrences"}, {"ko": "받다", "en": "to receive; to undergo", "note": "치료를 받다 = to undergo treatment"}, {"ko": "환자", "en": "patient", "note": "noun; 암 환자 = cancer patient"}, {"ko": "남다", "en": "to remain; to be left", "note": "intransitive; ~로 남다 = to remain/be left as"}, {"ko": "메시지", "en": "message", "note": "from English; common in modern Korean"}]', grammar = '{"patterns": [{"name": "~았/었어요 (passive)", "level": "Beginner", "exp": "Past tense ending expressing completed action. 올리다 (to post) → 올렸어요.", "ex_ko": "미국의 한 남성이 특별한 사진을 인터넷에 올렸어요.", "ex_en": "A man from the US posted a special photo on the internet."}, {"name": "의 (possessive particle)", "level": "Beginner", "exp": "Marks possession or attribution. Connects noun to noun: 미국 (US) + 의 → 미국의 (of/from the US).", "ex_ko": "미국의 한 남성이 특별한 사진을 인터넷에 올렸어요.", "ex_en": "A man from the US posted a special photo on the internet."}, {"name": "~다는 내용이다", "level": "Beginner", "exp": "Says what something was about: ''it was (about the fact) that…''. 알 수 있다 → 알 수 있다는 내용이었어요.", "ex_ko": "그의 여자친구가 항암 치료(암을 치료하는 의학적 방법)를 받은 횟수를 머리카락으로 알 수 있다는 내용이었어요.", "ex_en": "The content was that you could tell the number of times his girlfriend underwent cancer treatment by her hair."}, {"name": "~을/를 받다", "level": "Beginner", "exp": "받다 here means ''to receive'' or ''to undergo''. 치료를 받다 = to get treatment.", "ex_ko": "그의 여자친구가 항암 치료(암을 치료하는 의학적 방법)를 받은 횟수를 머리카락으로 알 수 있다는 내용이었어요.", "ex_en": "The content was that you could tell the number of times his girlfriend underwent cancer treatment by her hair."}, {"name": "~은/ㄴ (past participle modifier)", "level": "Beginner", "exp": "Modifies noun with past tense meaning. 받다 → 받은 (underwent). Modifies 횟수 (number of times).", "ex_ko": "그의 여자친구가 항암 치료(암을 치료하는 의학적 방법)를 받은 횟수를 머리카락으로 알 수 있다는 내용이었어요.", "ex_en": "The content was that you could tell the number of times his girlfriend underwent cancer treatment by her hair."}, {"name": "~으로 (transformative particle)", "level": "Beginner", "exp": "Marks transformation or state change. 흔적으로 (as/into traces).", "ex_ko": "그의 여자친구가 항암 치료(암을 치료하는 의학적 방법)를 받은 횟수를 머리카락으로 알 수 있다는 내용이었어요.", "ex_en": "The content was that you could tell the number of times his girlfriend underwent cancer treatment by her hair."}, {"name": "~으면 (conditional)", "level": "Beginner", "exp": "Conditional ending expressing ''if/when.'' 받다 → 받으면 (when receive/undergo).", "ex_ko": "항암 치료를 받으면 머리카락이 빠져요.", "ex_en": "When you undergo cancer treatment, your hair falls out."}, {"name": "~(으)면서", "level": "Beginner", "exp": "Means ''as'' or ''while'': two things happen together. 반복되다 → 반복되면서 (as it repeats).", "ex_ko": "치료가 끝나면 머리카락이 다시 자라요.", "ex_en": "When treatment ends, hair grows back again."}, {"name": "~도 (inclusive particle)", "level": "Beginner", "exp": "Adds ''even/too'' meaning to emphasize. 과정도 (even the process).", "ex_ko": "나무의 나이테처럼 머리카락에도 치료 횟수가 기록되었어요.", "ex_en": "Like the rings of a tree, the number of treatments was recorded in her hair too."}, {"name": "~고 (coordinating connective)", "level": "Beginner", "exp": "Connects two actions in sequence. 보다 (to see) → 보고, then 놀라워하다 (to be amazed).", "ex_ko": "많은 사람들이 이 사진을 보고 놀라워했어요.", "ex_en": "Many people saw this photo and were amazed."}, {"name": "~ㄴ/은 (past participle modifier)", "level": "Beginner", "exp": "Modifies noun with past action. 만들다 → 만든 (made). Modifies 기록 (record).", "ex_ko": "자연이 만든 신기한 기록이라고 말했어요.", "ex_en": "People said it was an amazing record made by nature."}, {"name": "~(이)라고 말하다", "level": "Beginner", "exp": "Quotes what someone said about a noun. 기록 + 이라고 말했어요 = said it was a record.", "ex_ko": "자연이 만든 신기한 기록이라고 말했어요.", "ex_en": "People said it was an amazing record made by nature."}, {"name": "~과/와 (connective particle)", "level": "Beginner", "exp": "Connects two nouns meaning ''and.'' 환자와 가족 (patients and families).", "ex_ko": "이 사진은 암 환자와 가족들에게 희망을 주었어요.", "ex_en": "This photo gave hope to cancer patients and their families."}, {"name": "~에게 (indirect object particle)", "level": "Beginner", "exp": "Marks recipient or target. 가족들에게 (to families).", "ex_ko": "이 사진은 암 환자와 가족들에게 희망을 주었어요.", "ex_en": "This photo gave hope to cancer patients and their families."}, {"name": "~(으)ㄹ 수 있다", "level": "Beginner", "exp": "Means ''can''. 남다 → 남을 수 있다 (can remain).", "ex_ko": "힘든 치료 과정도 아름다운 흔적으로 남을 수 있다는 메시지를 전했어요.", "ex_en": "They conveyed a message that even difficult treatment processes can remain as beautiful traces."}]}', updated_at = now() where article_id = 'movfkonk3oen' and md5(translation) = 'e4f7a5bb03d1cdb48cc05e1f045672a4';
update public.article_cache set translation = '{"texts": ["I saw a zebra in California, USA. The zebra was eating grass.", "Zebras normally live in Africa. However, there are also zebras in America. They are zebras that people raise.", "In the grassland, the zebra eats grass. The zebra has black and white stripes. It''s really beautiful.", "Many people say it''s fascinating. Seeing a zebra in America is not common."], "sentences": [{"text": "미국 캘리포니아에서 얼룩말을 봤어요.", "translation": "I saw a zebra in California, USA.", "vocab": [{"ko": "캘리포니아", "en": "California", "note": ""}, {"ko": "얼룩말", "en": "zebra", "note": ""}], "grammar": [{"pattern": "~았어요", "exp": "Past tense polite form indicating a completed action in the speaker''s personal experience.", "example_in_sentence": "봤어요"}], "analysis": []}, {"text": "얼룩말이 풀을 먹고 있었어요.", "translation": "The zebra was eating grass.", "vocab": [{"ko": "풀", "en": "grass", "note": ""}], "grammar": [{"pattern": "~고 있었어요", "exp": "Past progressive form describing an action in progress at a specific moment in the past.", "example_in_sentence": "먹고 있었어요"}], "analysis": []}, {"text": "얼룩말은 보통 아프리카에 살아요.", "translation": "Zebras normally live in Africa.", "vocab": [{"ko": "보통", "en": "normally; usually", "note": ""}, {"ko": "아프리카", "en": "Africa", "note": ""}], "grammar": [], "analysis": []}, {"text": "하지만 미국에도 있어요.", "translation": "However, there are also zebras in America.", "vocab": [{"ko": "하지만", "en": "but; however", "note": "Formal connective; introduces a contrasting clause."}], "grammar": [], "analysis": []}, {"text": "사람들이 키우는 얼룩말이에요.", "translation": "They are zebras that people raise.", "vocab": [{"ko": "사람", "en": "people; person", "note": ""}, {"ko": "키우다", "en": "to raise; to keep (an animal)", "note": ""}], "grammar": [], "analysis": []}, {"text": "풀밭에서 얼룩말이 풀을 먹어요.", "translation": "In the grassland, the zebra eats grass.", "vocab": [{"ko": "풀밭", "en": "grassland; meadow", "note": ""}], "grammar": [], "analysis": []}, {"text": "얼룩말은 검은색과 흰색 줄무늬가 있어요.", "translation": "The zebra has black and white stripes.", "vocab": [{"ko": "검은색", "en": "black (colour)", "note": ""}, {"ko": "흰색", "en": "white (colour)", "note": ""}, {"ko": "줄무늬", "en": "stripe; striped pattern", "note": ""}], "grammar": [], "analysis": []}, {"text": "정말 예뻐요.", "translation": "It''s really beautiful.", "vocab": [{"ko": "정말", "en": "really; very", "note": ""}, {"ko": "예쁘다", "en": "to be beautiful", "note": ""}], "grammar": [], "analysis": []}, {"text": "많은 사람들이 신기하다고 해요.", "translation": "Many people say it''s fascinating.", "vocab": [{"ko": "많다", "en": "to be many", "note": ""}, {"ko": "신기하다", "en": "to be fascinating; to be interesting/surprising", "note": ""}], "grammar": [{"pattern": "~다고 하다", "exp": "Quotative form expressing what people say or report; literally ''say that...''; used for indirect speech.", "example_in_sentence": "신기하다고 해요"}], "analysis": []}, {"text": "미국에서 얼룩말을 보는 것은 흔하지 않아요.", "translation": "Seeing a zebra in America is not common.", "vocab": [{"ko": "흔하다", "en": "to be common; to be usual", "note": ""}], "grammar": [{"pattern": "~는 것", "exp": "Nominalizer turning a verb phrase into a noun; ''the act of ~'' or ''~ as a thing''.", "example_in_sentence": "보는 것"}], "analysis": []}]}', vocab = '[{"ko": "캘리포니아", "en": "California", "note": ""}, {"ko": "얼룩말", "en": "zebra", "note": ""}, {"ko": "풀", "en": "grass", "note": ""}, {"ko": "보통", "en": "normally; usually", "note": ""}, {"ko": "아프리카", "en": "Africa", "note": ""}, {"ko": "하지만", "en": "but; however", "note": "Formal connective; introduces a contrasting clause."}, {"ko": "사람", "en": "people; person", "note": ""}, {"ko": "키우다", "en": "to raise; to keep (an animal)", "note": ""}, {"ko": "풀밭", "en": "grassland; meadow", "note": ""}, {"ko": "검은색", "en": "black (colour)", "note": ""}, {"ko": "흰색", "en": "white (colour)", "note": ""}, {"ko": "줄무늬", "en": "stripe; striped pattern", "note": ""}, {"ko": "정말", "en": "really; very", "note": ""}, {"ko": "예쁘